// Enhanced Express application with security best practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult, param } = require('express-validator');
require('dotenv').config();

const app = express();

// Security middleware setup
// 1. Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS configuration
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? process.env.ALLOWED_ORIGINS?.split(',') || []
    : ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// 3. Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4. Body parsing middleware with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Request logging middleware
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.url} - IP: ${req.ip}`);
  next();
});

// Health endpoint with improved response
app.get('/health', (req, res) => {
  try {
    const healthData = {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      environment: process.env.NODE_ENV || 'development'
    };
    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'unhealthy', 
      error: 'Internal server error',
      timestamp: new Date().toISOString() 
    });
  }
});

// Users endpoint with input validation for query parameters
app.get('/users', 
  // Validation middleware
  [
    param('id').optional().isInt({ min: 1 }).withMessage('ID must be a positive integer'),
  ],
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          errors: errors.array(),
          message: 'Validation failed' 
        });
      }

      // Example: Filter users by ID if provided
      const userId = req.query.id;
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
        { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
      ];

      let responseData;
      if (userId) {
        responseData = users.filter(user => user.id === parseInt(userId, 10));
        if (responseData.length === 0) {
          return res.status(404).json({ 
            message: 'User not found',
            requestedId: userId 
          });
        }
      } else {
        responseData = users;
      }

      // Sanitize sensitive data before sending
      const sanitizedData = responseData.map(user => ({
        id: user.id,
        name: user.name,
        role: user.role
        // Email omitted for security in this example
      }));

      res.json({
        data: sanitizedData,
        count: sanitizedData.length,
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      console.error('Users endpoint error:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: 'Failed to retrieve users',
        timestamp: new Date().toISOString() 
      });
    }
  }
);

// Example POST endpoint with comprehensive validation
app.post('/users',
  [
    body('name')
      .trim()
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s]+$/)
      .withMessage('Name can only contain letters and spaces'),
    body('email')
      .trim()
      .isEmail()
      .withMessage('Must be a valid email address')
      .normalizeEmail(),
    body('age')
      .optional()
      .isInt({ min: 1, max: 120 })
      .withMessage('Age must be between 1 and 120'),
    body('role')
      .optional()
      .isIn(['user', 'admin', 'moderator'])
      .withMessage('Invalid role specified')
  ],
  (req, res) => {
    try {
      // Validate input
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          errors: errors.array(),
          message: 'Validation failed' 
        });
      }

      // Sanitize and process data
      const userData = {
        name: req.body.name,
        email: req.body.email,
        age: req.body.age,
        role: req.body.role || 'user',
        createdAt: new Date().toISOString()
      };

      // In a real app, you would save to database here
      console.log('New user created:', { ...userData, email: '[REDACTED]' });

      res.status(201).json({
        message: 'User created successfully',
        data: userData,
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      console.error('Create user error:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: 'Failed to create user',
        timestamp: new Date().toISOString() 
      });
    }
  }
);

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.url} not found`,
    timestamp: new Date().toISOString()
  });
});

// Global error handling middleware (must be last)
app.use((error, req, res, next) => {
  console.error('Unhandled error:', {
    error: error.message,
    stack: error.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't expose internal error details in production
  const isProduction = process.env.NODE_ENV === 'production';
  const response = {
    error: 'Internal Server Error',
    message: isProduction ? 'Something went wrong' : error.message,
    timestamp: new Date().toISOString()
  };

  res.status(error.status || 500).json(response);
});

// Server startup with error handling
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running in ${process.env.NODE_ENV || 'development'} mode on port ${PORT}`);
});

// Graceful shutdown handling
const shutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);
  server.close(() => {
    console.log('HTTP server closed.');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;

