// Secure Express.js application with enhanced error handling and security
// Improved version based on security best practices

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { validationResult, query } = require('express-validator');
const winston = require('winston');

// Initialize Express app
const app = express();

// ========== 1. SECURITY MIDDLEWARE ==========

// Set security headers using Helmet
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            scriptSrc: ["'self'"],
            styleSrc: ["'self'"],
            imgSrc: ["'self'", "data:"],
        },
    },
    hidePoweredBy: true,  // Remove X-Powered-By header
    hsts: {
        maxAge: 31536000, // 1 year
        includeSubDomains: true,
        preload: true
    },
    frameguard: { action: 'deny' }, // Prevent clickjacking
    noSniff: true, // Prevents MIME type sniffing
    referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// Configure CORS
app.use(cors({
    origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : [],
    methods: ['GET', 'POST'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true
}));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: {
        error: 'Too many requests, please try again later.',
        statusCode: 429
    },
    standardHeaders: true,
    legacyHeaders: false
});

// Apply rate limiting to all routes
app.use(limiter);

// ========== 2. LOGGING CONFIGURATION ==========

// Configure Winston logger
const logger = winston.createLogger({
    level: process.env.LOG_LEVEL || 'info',
    format: winston.format.combine(
        winston.format.timestamp(),
        winston.format.errors({ stack: true }),
        winston.format.json()
    ),
    transports: [
        new winston.transports.Console({
            format: winston.format.combine(
                winston.format.colorize(),
                winston.format.simple()
            )
        }),
        new winston.transports.File({ filename: 'error.log', level: 'error' }),
        new winston.transports.File({ filename: 'combined.log' })
    ]
});

// Request logging middleware
app.use((req, res, next) => {
    const start = Date.now();

    res.on('finish', () => {
        const duration = Date.now() - start;
        logger.info('Request completed', {
            method: req.method,
            url: req.url,
            status: res.statusCode,
            duration: `${duration}ms`,
            ip: req.ip,
            userAgent: req.get('User-Agent')
        });
    });

    next();
});

// ========== 3. INPUT VALIDATION SCHEMAS ==========

// Validation schemas for endpoints
const userQueryValidation = [
    query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    query('sort').optional().isIn(['name', 'id', 'email']).withMessage('Sort must be one of: name, id, email'),
    query('search').optional().isString().trim().escape().withMessage('Search query must be a valid string')
];

// ========== 4. ENHANCED ENDPOINTS WITH VALIDATION ==========

// Health check endpoint with additional diagnostic info
app.get('/health', (req, res) => {
    try {
        const healthData = {
            status: 'healthy',
            timestamp: new Date().toISOString(),
            uptime: process.uptime(),
            memory: process.memoryUsage(),
            environment: process.env.NODE_ENV || 'development'
        };

        res.json(healthData);
    } catch (error) {
        logger.error('Health check failed', { error: error.message, stack: error.stack });
        res.status(500).json({ error: 'Health check failed', status: 'unhealthy' });
    }
});

// Users endpoint with comprehensive validation and error handling
app.get('/users', userQueryValidation, (req, res) => {
    try {
        // Check for validation errors
        const errors = validationResult(req);
        if (!errors.isEmpty()) {
            logger.warn('Validation errors in /users endpoint', { errors: errors.array() });
            return res.status(400).json({
                error: 'Validation failed',
                details: errors.array().map(err => ({
                    field: err.param,
                    message: err.msg,
                    value: err.value
                }))
            });
        }

        // Extract and sanitize query parameters
        const { page = 1, limit = 10, sort = 'id', search = '' } = req.query;
        const pageNum = parseInt(page);
        const limitNum = parseInt(limit);

        // Simulate user data (in real app, this would come from database)
        let users = [
            { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: '2024-01-01' },
            { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: '2024-01-02' },
        ];

        // Add more sample users for pagination demonstration
        for (let i = 3; i <= 50; i++) {
            users.push({ 
                id: i, 
                name: `User${i}`, 
                email: `user${i}@example.com`, 
                createdAt: `2024-01-${i.toString().padStart(2, '0')}` 
            });
        }

        // Apply search filter if provided
        if (search) {
            const searchLower = search.toLowerCase();
            users = users.filter(user => 
                user.name.toLowerCase().includes(searchLower) || 
                user.email.toLowerCase().includes(searchLower)
            );
        }

        // Apply sorting
        users.sort((a, b) => {
            if (sort === 'name') return a.name.localeCompare(b.name);
            if (sort === 'email') return a.email.localeCompare(b.email);
            return a.id - b.id;
        });

        // Apply pagination
        const startIndex = (pageNum - 1) * limitNum;
        const endIndex = pageNum * limitNum;
        const paginatedUsers = users.slice(startIndex, endIndex);
        const totalPages = Math.ceil(users.length / limitNum);

        // Sanitize output (prevent information leakage)
        const safeUsers = paginatedUsers.map(user => ({
            id: user.id,
            name: user.name,
            email: user.email
            // Note: createdAt omitted from response to minimize data exposure
        }));

        res.json({
            data: safeUsers,
            pagination: {
                page: pageNum,
                limit: limitNum,
                totalItems: users.length,
                totalPages: totalPages,
                hasNextPage: pageNum < totalPages,
                hasPrevPage: pageNum > 1
            },
            meta: {
                sortBy: sort,
                searchTerm: search || null
            }
        });

    } catch (error) {
        logger.error('Error processing /users request', { 
            error: error.message, 
            stack: error.stack,
            query: req.query,
            ip: req.ip
        });

        // Don't expose internal error details in production
        if (process.env.NODE_ENV === 'production') {
            res.status(500).json({ error: 'Internal server error' });
        } else {
            res.status(500).json({ 
                error: 'Internal server error during user retrieval',
                message: error.message 
            });
        }
    }
});

// ========== 5. ERROR HANDLING MIDDLEWARE ==========

// 404 handler for unknown routes
app.use((req, res) => {
    logger.warn('Route not found', { method: req.method, url: req.url, ip: req.ip });
    res.status(404).json({
        error: 'Route not found',
        message: `${req.method} ${req.url} is not a valid endpoint`
    });
});

// Global error handler
app.use((error, req, res, next) => {
    logger.error('Unhandled error', {
        error: error.message,
        stack: error.stack,
        method: req.method,
        url: req.url,
        ip: req.ip,
        body: req.body,
        query: req.query
    });

    const statusCode = error.statusCode || 500;
    const response = {
        error: 'Internal server error',
        timestamp: new Date().toISOString()
    };

    // Include additional info in non-production environments
    if (process.env.NODE_ENV !== 'production') {
        response.message = error.message;
        if (error.validationErrors) {
            response.validationErrors = error.validationErrors;
        }
    }

    res.status(statusCode).json(response);
});

// ========== 6. SERVER SETUP WITH GRACEFUL SHUTDOWN ==========

// Get port from environment variable with fallback
const PORT = process.env.PORT || 3000;

// Start server
const server = app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
    console.log(`Server is running on http://localhost:${PORT}`);
});

// Graceful shutdown handling
const gracefulShutdown = () => {
    logger.info('Received shutdown signal, initiating graceful shutdown...');

    server.close(() => {
        logger.info('HTTP server closed');
        process.exit(0);
    });

    // Force shutdown after timeout
    setTimeout(() => {
        logger.error('Could not close connections in time, forcefully shutting down');
        process.exit(1);
    }, 10000);
};

// Listen for shutdown signals
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
    logger.error('Uncaught Exception:', { error: error.message, stack: error.stack });
    gracefulShutdown();
});

process.on('unhandledRejection', (reason, promise) => {
    logger.error('Unhandled Rejection at:', { promise, reason });
    gracefulShutdown();
});

module.exports = { app, server, logger };

