// Minimal secure version of app.js with essential security improvements
const express = require('express');
const app = express();

// ========== ESSENTIAL SECURITY MIDDLEWARE ==========

// 1. Basic security headers
app.use((req, res, next) => {
    // Remove X-Powered-By header
    res.removeHeader('X-Powered-By');

    // Set security headers
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('X-Frame-Options', 'DENY');
    res.setHeader('X-XSS-Protection', '1; mode=block');
    res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

    next();
});

// 2. Input validation middleware
const validateUserQuery = (req, res, next) => {
    const errors = [];

    // Validate query parameters if provided
    if (req.query.page) {
        const page = parseInt(req.query.page);
        if (isNaN(page) || page < 1) {
            errors.push({ field: 'page', message: 'Page must be a positive integer' });
        }
    }

    if (req.query.limit) {
        const limit = parseInt(req.query.limit);
        if (isNaN(limit) || limit < 1 || limit > 100) {
            errors.push({ field: 'limit', message: 'Limit must be between 1 and 100' });
        }
    }

    if (errors.length > 0) {
        return res.status(400).json({
            error: 'Validation failed',
            details: errors
        });
    }

    // Sanitize inputs
    if (req.query.search) {
        req.query.search = req.query.search.trim().replace(/[<>]/g, '');
    }

    next();
};

// 3. Global error handler
const errorHandler = (err, req, res, next) => {
    console.error('Unhandled error:', {
        message: err.message,
        stack: err.stack,
        url: req.url,
        method: req.method,
        timestamp: new Date().toISOString()
    });

    // Don't expose error details in production
    const isDevelopment = process.env.NODE_ENV === 'development';
    const errorResponse = {
        error: 'Internal server error',
        timestamp: new Date().toISOString()
    };

    if (isDevelopment) {
        errorResponse.message = err.message;
    }

    res.status(500).json(errorResponse);
};

// ========== ENHANCED ENDPOINTS ==========

app.get('/health', (req, res) => {
    try {
        res.json({ 
            status: 'ok', 
            timestamp: new Date().toISOString() 
        });
    } catch (error) {
        console.error('Health endpoint error:', error);
        res.status(500).json({ error: 'Health check failed' });
    }
});

app.get('/users', validateUserQuery, (req, res) => {
    try {
        // Parse and validate pagination
        const page = parseInt(req.query.page) || 1;
        const limit = parseInt(req.query.limit) || 10;

        // Ensure limits are reasonable
        const safeLimit = Math.min(limit, 100);
        const safePage = Math.max(page, 1);

        // Mock user data with safe output
        const users = [
            { 
                id: 1, 
                name: 'Alice', 
                email: 'alice@example.com' 
            },
            { 
                id: 2, 
                name: 'Bob', 
                email: 'bob@example.com' 
            },
        ];

        // Return safe response with pagination info
        res.json({
            data: users,
            pagination: {
                page: safePage,
                limit: safeLimit,
                total: users.length
            }
        });
    } catch (error) {
        console.error('Users endpoint error:', {
            error: error.message,
            query: req.query,
            timestamp: new Date().toISOString()
        });

        res.status(500).json({ 
            error: 'Failed to retrieve users',
            ...(process.env.NODE_ENV === 'development' && { message: error.message })
        });
    }
});

// 404 handler
app.use((req, res) => {
    res.status(404).json({
        error: 'Not found',
        message: `${req.method} ${req.url} not found`
    });
});

// Apply global error handler
app.use(errorHandler);

// ========== SERVER SETUP ==========
