function validateEnvironment() {
  const requiredVars = [];
  const optionalVars = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 
                       'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'];

  console.log('Environment validation:');

  // Check for required variables
  requiredVars.forEach(variable => {
    if (!process.env[variable]) {
      console.error(`❌ Missing required environment variable: ${variable}`);
      process.exit(1);
    }
    console.log(`✅ Required variable present: ${variable} (value hidden)`);
  });

  // Log presence of optional variables (without values for security)
  optionalVars.forEach(variable => {
    if (process.env[variable]) {
      console.log(`⚠️  Sensitive variable present: ${variable} (value hidden)`);
    } else {
      console.log(`✅ Optional variable not set: ${variable}`);
    }
  });
}

// Basic input validation middleware
const validateInput = (req, res, next) => {
  // Check for common injection patterns in query parameters
  const suspiciousPatterns = [
    /(\%27)|(\')|(\-\-)|(\%23)|(#)/i, // SQL injection patterns
    /<script.*?>.*?<\/script>/i, // Basic XSS pattern
    /(\b)(SELECT|INSERT|UPDATE|DELETE|DROP|UNION)(\b)/i // Basic SQL keywords
  ];

  // Check query parameters
  Object.keys(req.query).forEach(key => {
    const value = req.query[key];
    suspiciousPatterns.forEach(pattern => {
      if (pattern.test(value)) {
        console.warn(`⚠️  Potential injection attempt detected in ${key}: ${value.substring(0, 50)}...`);
        // Log but don't block - could be legitimate in some cases
      }
    });
  });

  next();
};

// Apply input validation to all routes
app.use(validateInput);

