});
app.use('/api/', limiter);

// 4. Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================
// Logging Configuration
// ============================

const logger = winston.createLogger({
    level: process.env.NODE_ENV === 'production' ? 'info' : 'debug',
    format: winston.format.combine(
        winston.format.timestamp(),
        winston.format.errors({ stack: true }),
        winston.format.json()
    ),
    transports: [
        new winston.transports.File({ filename: 'error.log', level: 'error' }),
        new winston.transports.File({ filename: 'combined.log' }),
        ...(process.env.NODE_ENV !== 'production' 
            ? [new winston.transports.Console({ format: winston.format.simple() })] 
            : [])
    ]
});

// Logging middleware
app.use((req, res, next) => {
    logger.info(`${req.method} ${req.url}`, {
        ip: req.ip,
        userAgent: req.get('User-Agent'),
        timestamp: new Date().toISOString()
    });
    next();
});

// ============================
// Error Handling Middleware
// ============================

// Global error handler
const errorHandler = (err, req, res, next) => {
    logger.error('Unhandled error:', {
        message: err.message,
        stack: err.stack,
        url: req.url,
        method: req.method,
        ip: req.ip
    });

    // Don't expose internal error details in production
    const errorResponse = process.env.NODE_ENV === 'production'
        ? { error: 'An unexpected error occurred' }
        : { error: err.message, stack: err.stack };

    res.status(err.status || 500).json(errorResponse);
};

// 404 handler
const notFoundHandler = (req, res, next) => {
    logger.warn(`404 Not Found: ${req.method} ${req.url}`);
    res.status(404).json({ error: 'Resource not found' });
};

// ============================
// Input Validation Middleware
// ============================

const validateRequest = (validations) => {
    return async (req, res, next) => {
        await Promise.all(validations.map(validation => validation.run(req)));

        const errors = validationResult(req);
        if (!errors.isEmpty()) {
            logger.warn(`Input validation failed: ${JSON.stringify(errors.array())}`);
            return res.status(400).json({ 
                error: 'Validation failed', 
                details: errors.array() 
            });
        }
        next();
    };
};

// ============================
// Route Definitions with Validation
// ============================

// Health endpoint with validation
app.get('/health', (req, res) => {
    try {
        res.json({ 
            status: 'ok', 
            timestamp: new Date().toISOString(),
            uptime: process.uptime(),
            memoryUsage: process.memoryUsage()
        });
    } catch (error) {
        logger.error('Health endpoint error:', error);
        res.status(500).json({ error: 'Health check failed' });
    }
});

// Users endpoint with validation and pagination
app.get('/users', 
    validateRequest([
        body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
        body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100')
    ]),
    async (req, res, next) => {
        try {
            const { page = 1, limit = 10 } = req.body;

            // Simulated database query with error handling
            const users = [
                { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: new Date().toISOString() },
                { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: new Date().toISOString() },
            ];

            // Sanitize output (remove sensitive data if needed)
            const sanitizedUsers = users.map(user => ({
                id: user.id,
                name: user.name,
                email: user.email
                // Don't send createdAt in response
            }));

            res.json({
                data: sanitizedUsers,
                pagination: {
                    page: parseInt(page),
                    limit: parseInt(limit),
                    total: users.length
                }
            });

        } catch (error) {
            logger.error('Users endpoint error:', error);
            next(error);
        }
    }
);

// Get user by ID with validation
app.get('/users/:id',
    validateRequest([
        param('id').isInt({ min: 1 }).withMessage('ID must be a positive integer')
    ]),
    async (req, res, next) => {
        try {
            const userId = parseInt(req.params.id);

            const user = { 
                id: userId, 
                name: 'Test User', 
                email: 'test@example.com' 
            };

            if (!user) {
                return res.status(404).json({ error: 'User not found' });
            }

            res.json(user);

        } catch (error) {
            logger.error('Get user by ID error:', error);
            next(error);
        }
    }
);

// Create user endpoint with comprehensive validation
app.post('/users',
    validateRequest([
        body('name')
            .trim()
            .notEmpty().withMessage('Name is required')
            .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
            .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces')
            .escape(),
        body('email')
            .trim()
            .notEmpty().withMessage('Email is required')
            .isEmail().withMessage('Valid email is required')
            .normalizeEmail(),
        body('age')
            .optional()
            .isInt({ min: 0, max: 120 }).withMessage('Age must be between 0 and 120'),
        body('password')
            .optional()
            .isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
            .matches(/[A-Z]/).withMessage('Password must contain at least one uppercase letter')
            .matches(/[a-z]/).withMessage('Password must contain at least one lowercase letter')
            .matches(/[0-9]/).withMessage('Password must contain at least one number')
    ]),
    async (req, res, next) => {
        try {
            const { name, email, age } = req.body;

            // Additional business logic validation
            if (age && age < 13) {
                return res.status(400).json({ error: 'User must be at least 13 years old' });
            }

            // Simulate user creation
            const newUser = {
                id: Math.floor(Math.random() * 1000),
                name,
                email,
                age: age || null,
                createdAt: new Date().toISOString()
            };

            logger.info(`New user created: ${email}`);

            // Return created user (without sensitive data)
            res.status(201).json({
                message: 'User created successfully',
                user: {
                    id: newUser.id,
                    name: newUser.name,
                    email: newUser.email
                }
            });

        } catch (error) {
            logger.error('Create user error:', error);
            next(error);
        }
    }
);

// ============================
// Security Monitoring Endpoint
// ============================

app.get('/security/logs', (req, res) => {
    // This endpoint should be protected in production
    if (process.env.NODE_ENV === 'production' && req.ip !== '127.0.0.1') {
        return res.status(403).json({ error: 'Access denied' });
    }

    // In a real app, you would read logs from a file or database
    res.json({ 
        message: 'Security logs endpoint',
        note: 'This should be protected in production' 
    });
});

// ============================
// Apply Error Handlers
// ============================

// Apply 404 handler for undefined routes
app.use(notFoundHandler);

// Apply global error handler
app.use(errorHandler);

// ============================
// Server Startup with Graceful Shutdown
// ============================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);

    // Log security headers being used
    logger.info('Security headers enabled: Helmet.js');
    logger.info('Rate limiting enabled: 100 requests/15min per IP');
    logger.info('CORS configured for production environment');
});

// Graceful shutdown
process.on('SIGTERM', () => {
    logger.info('SIGTERM received. Starting graceful shutdown...');
    server.close(() => {
        logger.info('Server closed. Process terminated.');
        process.exit(0);
    });
});

process.on('SIGINT', () => {
    logger.info('SIGINT received. Starting graceful shutdown...');
    server.close(() => {
        logger.info('Server closed. Process terminated.');
        process.exit(0);
    });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
    logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
    logger.error('Uncaught Exception:', error);
    process.exit(1);
});

module.exports = app;

