app.get('/users', [
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt().default(10),
  query('page').optional().isInt({ min: 1 }).toInt().default(1),
  query('active').optional().isBoolean().toBoolean()
], req.validateRequest([]), (req, res) => {
  try {
    const { limit = 10, page = 1, active } = req.query;

    // Simulated user data - in real app, this would come from a database
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        isActive: true 
      },
      { 
        id: 2, 
        name: 'Bob', 
