/**
 * Improved Express.js application with enhanced security and error handling
 */

const express = require('express');
const helmet = require('helmet'); // Security middleware
const rateLimit = require('express-rate-limit'); // Rate limiting
const cors = require('cors'); // CORS configuration

const app = express();

// ==============================================
// SECURITY MIDDLEWARE
// ==============================================

// HTTP header security
app.use(helmet());

// Configure CORS properly
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] // Production domain
    : ['http://localhost:3000', 'http://localhost:3001'], // Development domains
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// Rate limiting to prevent brute force attacks
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(apiLimiter);

// Body parsing with limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ==============================================
// INPUT VALIDATION MIDDLEWARE
// ==============================================

function validateEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

function validateId(id) {
  return typeof id === 'number' && Number.isInteger(id) && id > 0;
}

function sanitizeString(input) {
  return input.toString().trim().replace(/[<>"'`]/g, '');
}

// ==============================================
// ERROR HANDLING UTILITIES
// ==============================================

class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Global error handler middleware
function errorHandler(err, req, res, next) {
  console.error('Error:', err);

  // Default error status
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Different response based on environment
  if (process.env.NODE_ENV === 'development') {
    return res.status(err.statusCode).json({
      status: err.status,
      error: err,
      message: err.message,
      stack: err.stack
    });
  }

  // Production response (hide sensitive info)
  if (err.isOperational) {
    // Operational, trusted error: send message to client
    return res.status(err.statusCode).json({
      status: err.status,
      message: err.message
    });
  }

  // Programming or unknown error: don't leak details
  return res.status(500).json({
    status: 'error',
    message: 'Something went wrong!'
  });
}

// Async error wrapper
function asyncHandler(fn) {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

// ==============================================
// ROUTES WITH PROPER VALIDATION
// ==============================================

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Health check failed',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with input validation
app.get('/users', asyncHandler(async (req, res, next) => {
  // Validate query parameters if any
  const { limit, offset } = req.query;

  if (limit && (!Number.isInteger(Number(limit)) || Number(limit) < 1 || Number(limit) > 100)) {
    return next(new AppError('Limit must be an integer between 1 and 100', 400));
  }

  if (offset && (!Number.isInteger(Number(offset)) || Number(offset) < 0)) {
    return next(new AppError('Offset must be a non-negative integer', 400));
  }

  // Simulating database fetch with error handling
  const users = [
    { 
      id: 1, 
      name: sanitizeString('Alice'), 
      email: 'alice@example.com'
    },
    { 
      id: 2, 
      name: sanitizeString('Bob'), 
      email: 'bob@example.com' 
    },
  ];

  res.json({
    success: true,
    data: users,
    count: users.length,
    limit: limit ? parseInt(limit) : null,
    offset: offset ? parseInt(offset) : null
  });
}));

// New endpoint with parameter validation
app.get('/users/:id', asyncHandler(async (req, res, next) => {
  const userId = parseInt(req.params.id);

  // Validate ID parameter
  if (!validateId(userId)) {
    return next(new AppError('Invalid user ID format', 400));
  }

  // Simulate database lookup
  if (userId === 1) {
    res.json({
      success: true,
      data: {
        id: userId,
        name: sanitizeString('Alice'),
        email: 'alice@example.com'
      }
    });
  } else if (userId === 2) {
    res.json({
      success: true,
      data: {
        id: userId,
        name: sanitizeString('Bob'),
        email: 'bob@example.com'
      }
    });
  } else {
    return next(new AppError('User not found', 404));
  }
}));

// New safe user creation endpoint
app.post('/users', asyncHandler(async (req, res, next) => {
  const { name, email } = req.body;

  // Input validation
  if (!name || typeof name !== 'string' || name.trim().length < 2 || name.trim().length > 50) {
    return next(new AppError('Name must be a string between 2 and 50 characters', 400));
  }

  if (!email || !validateEmail(email)) {
    return next(new AppError('Invalid email format', 400));
  }

  // Sanitize inputs
  const sanitizedName = sanitizeString(name);
  const sanitizedEmail = email.toLowerCase().trim();

  // Simulate user creation
  const newUser = {
    id: 3, // Simulated ID
    name: sanitizedName,
    email: sanitizedEmail,
    created: new Date().toISOString()
  };

  res.status(201).json({
    success: true,
    message: 'User created successfully',
    data: newUser
  });
}));

// ==============================================
// 404 HANDLER
// ==============================================

app.use('*', (req, res, next) => {
  next(new AppError(`Cannot find ${req.originalUrl} on this server`, 404));
});

// ==============================================
// ERROR HANDLER
// ==============================================

app.use(errorHandler);

// ==============================================
// SERVER CONFIGURATION
// ==============================================

const PORT = process.env.PORT || 3000;

// Graceful shutdown
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  // Close server gracefully
  server.close(() => {
    console.log('Server closed due to unhandled rejection');
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

// Graceful shutdown signals
['SIGTERM', 'SIGINT'].forEach(signal => {
  process.on(signal, () => {
    console.log(`\n${signal} signal received: closing HTTP server`);
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });
  });
});

module.exports = { app, server };

