/**
 * Secure version of app.js with error handling and input validation
 * Focuses on security best practices while maintaining original functionality
 */

const express = require('express');
const app = express();

// ==============================================
// SECURITY ENHANCEMENTS
// ==============================================

// 1. Basic security headers (manual implementation without helmet dependency)
app.use((req, res, next) => {
  // Security headers to prevent common attacks
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Prevent caching of sensitive data
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
  res.setHeader('Pragma', 'no-cache');
  res.setHeader('Expires', '0');

  next();
});

// 2. Body size limits to prevent DoS attacks
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// ==============================================
// INPUT VALIDATION FUNCTIONS
// ==============================================

// Validate and sanitize string inputs
function validateAndSanitizeString(input) {
  if (typeof input !== 'string') {
    throw new Error('Input must be a string');
  }

  // Trim and remove excessive whitespace
  let sanitized = input.trim().replace(/\s+/g, ' ');

  // Remove potentially dangerous characters for XSS prevention
  sanitized = sanitized.replace(/[<>"'`]/g, '');

  // Length validation
  if (sanitized.length < 1 || sanitized.length > 255) {
    throw new Error('String must be between 1 and 255 characters');
  }

  return sanitized;
}

// Validate numeric ID
function validateId(id) {
  const numId = Number(id);
  if (!Number.isInteger(numId) || numId <= 0) {
    throw new Error('ID must be a positive integer');
  }
  return numId;
}

// Validate email format
function validateEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    throw new Error('Invalid email format');
  }
  return email.toLowerCase().trim();
}

// ==============================================
// ERROR HANDLING MIDDLEWARE
// ==============================================

// Centralized error handler
function errorHandler(err, req, res, next) {
  console.error(`[${new Date().toISOString()}] Error:`, {
    path: req.path,
    method: req.method,
    error: err.message,
    // Only show stack trace in development
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  // Determine appropriate status code
  let statusCode = 500;
  let message = 'Internal server error';

  if (err.message.includes('must be')) {
    statusCode = 400; // Bad request for validation errors
    message = err.message;
  } else if (err.message.includes('Invalid') || err.message.includes('valid')) {
    statusCode = 400;
    message = err.message;
  }

  // Send appropriate response
  res.status(statusCode).json({
    success: false,
    error: message,
    timestamp: new Date().toISOString()
  });
}

// Async error wrapper
function asyncHandler(fn) {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

// ==============================================
// SECURE ENDPOINTS
// ==============================================

// Health endpoint with improved error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: `${Math.round(process.memoryUsage().heapUsed / 1024 / 1024)}MB`
    });
  } catch (error) {
    // Log the error but return a sanitized response
    console.error('Health check error:', error);
    res.status(503).json({ 
      status: 'error', 
      timestamp: new Date().toISOString(),
      message: 'Service temporarily unavailable'
    });
  }
});

// Users endpoint with input validation
app.get('/users', asyncHandler(async (req, res) => {
  // Validate query parameters if provided
  const { limit, offset } = req.query;

  let validatedLimit = 10; // Default
  let validatedOffset = 0; // Default

  if (limit) {
    validatedLimit = validateId(limit);
    if (validatedLimit > 100) {
      throw new Error('Limit must not exceed 100');
    }
  }

  if (offset) {
    validatedOffset = validateId(offset);
  }

  // Simulated user data (in production, this would come from a database)
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply pagination (simplified)
  const users = allUsers.slice(validatedOffset, validatedOffset + validatedLimit);

  res.json({
    success: true,
    data: users,
    pagination: {
      total: allUsers.length,
      limit: validatedLimit,
      offset: validatedOffset,
      returned: users.length
    },
    timestamp: new Date().toISOString()
  });
}));

// Additional secure endpoint example
app.get('/users/:id', asyncHandler(async (req, res) => {
  const userId = validateId(req.params.id);

  // Simulated database lookup
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    throw new Error(`User with ID ${userId} not found`);
  }

  res.json({
    success: true,
    data: user,
    timestamp: new Date().toISOString()
  });
}));

// ==============================================
// 404 HANDLER
// ==============================================

app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: `Cannot ${req.method} ${req.originalUrl}`,
    timestamp: new Date().toISOString()
  });
});

// ==============================================
// GLOBAL ERROR HANDLER
// ==============================================

app.use(errorHandler);

// ==============================================
// SERVER STARTUP WITH ERROR HANDLING
// ==============================================

const PORT = process.env.PORT || 3000;

// Graceful error handling for server startup
try {
  const server = app.listen(PORT, () => {
    console.log(`Secure server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Graceful shutdown handling
  process.on('SIGTERM', () => {
    console.log('SIGTERM received: closing server gracefully');
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });
  });

  process.on('SIGINT', () => {
    console.log('SIGINT received: closing server gracefully');
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });
  });

} catch (error) {
  console.error('Failed to start server:', error);
  process.exit(1);
}

module.exports = app;

