// Enhanced application with improved error handling and input validation
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, param, validationResult } = require('express-validator');
const winston = require('winston');

// Initialize logger
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ],
});

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS configuration (adjust as needed for your use case)
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

// Rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// Body parsing with size limits
app.use(express.json({
  limit: '10kb', // Prevent large payloads
  strict: true // Only accept arrays and objects
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// Health check endpoint with validation
app.get('/health', [
  // Add any query parameter validation if needed
], (req, res) => {
  try {
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memoryUsage: process.memoryUsage()
    };

    // Log health check
    logger.info('Health check performed', { 
      endpoint: '/health',
      timestamp: new Date().toISOString()
    });

    res.json(healthData);
  } catch (error) {
    logger.error('Health check failed', {
      endpoint: '/health',
      error: error.message,
      stack: error.stack
    });
    res.status(500).json({
      status: 'error',
      message: 'Internal server error during health check'
    });
  }
});

// Users endpoint with input validation
app.get('/users', [
  // Validate query parameters if you add search/filter functionality
], (req, res) => {
  try {
    // Simulate database access with error handling
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Sanitize outputs (though these are static, it's good practice)
    const sanitizedUsers = users.map(user => ({
      id: parseInt(user.id) || user.id, // Ensure ID is a number
      name: String(user.name).substring(0, 100), // Limit name length
      email: String(user.email).substring(0, 255) // Limit email length
    }));

    logger.info('Users list retrieved', { 
      endpoint: '/users',
      userCount: sanitizedUsers.length
    });

    res.json(sanitizedUsers);
  } catch (error) {
    logger.error('Failed to retrieve users', {
      endpoint: '/users',
      error: error.message,
      stack: error.stack
    });
    res.status(500).json({
      error: 'Internal server error',
      message: 'Could not retrieve user data'
    });
  }
});

// Example endpoint with parameter validation
app.get('/users/:id', [
  param('id')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer')
    .toInt(),
], (req, res) => {
  try {
    // Check validation results
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn('Invalid user ID parameter', {
        endpoint: '/users/:id',
        errors: errors.array(),
        providedId: req.params.id
      });
      return res.status(400).json({ 
        errors: errors.array(),
        message: 'Invalid user ID parameter'
      });
    }

    const userId = req.params.id;
    logger.info('User details requested', { 
      endpoint: '/users/:id',
      userId
    });

    // Simulate user lookup
    if (userId === '1') {
      res.json({ id: 1, name: 'Alice', email: 'alice@example.com' });
    } else if (userId === '2') {
      res.json({ id: 2, name: 'Bob', email: 'bob@example.com' });
    } else {
      logger.warn('User not found', { 
        endpoint: '/users/:id',
        userId
      });
      res.status(404).json({ 
        error: 'Not Found',
        message: 'User not found'
      });
    }
  } catch (error) {
    logger.error('Failed to retrieve user', {
      endpoint: '/users/:id',
      userId: req.params.id,
      error: error.message,
      stack: error.stack
    });
    res.status(500).json({
      error: 'Internal server error',
      message: 'Could not retrieve user data'
    });
  }
});

// Global error handling middleware
app.use((err, req, res, next) => {
  // Log the error
  logger.error('Unhandled error', {
    endpoint: req.path,
    method: req.method,
    error: err.message,
    stack: err.stack,
    timestamp: new Date().toISOString()
  });

  // Don't leak stack traces in production
  const isProduction = process.env.NODE_ENV === 'production';
  const errorResponse = {
    error: 'Internal Server Error',
    message: isProduction ? 'An unexpected error occurred' : err.message,
    ...(isProduction ? {} : { stack: err.stack })
  };

  res.status(err.status || 500).json(errorResponse);
});

// Handle 404 errors
app.use((req, res, next) => {
  logger.warn('Endpoint not found', {
    endpoint: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  res.status(404).json({
    error: 'Not Found',
    message: 'The requested endpoint does not exist'
  });
});

// Default error handler for unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', {
    promise: promise,
    reason: reason
  });
});

process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', {
    error: error.message,
    stack: error.stack
  });
  // In production, you might want to gracefully shutdown
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// Get port from environment variable or use default
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

const server = app.listen(PORT, HOST, () => {
  logger.info(`Server running on ${HOST}:${PORT}`, {
    environment: process.env.NODE_ENV || 'development',
    timestamp: new Date().toISOString()
  });
});

// Graceful shutdown
const gracefulShutdown = (signal) => {
  logger.info(`${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });

  // Force close after timeout
  setTimeout(() => {
    logger.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = { app, server };

