// Secure Express.js Application with Enhanced Error Handling and Input Validation
// Security best practices implemented

const express = require('express');
const helmet = require('helmet'); // Security headers middleware
const cors = require('cors'); // CORS configuration
const rateLimit = require('express-rate-limit'); // Rate limiting
const { body, param, query, validationResult } = require('express-validator'); // Input validation
const morgan = require('morgan'); // HTTP request logging

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// 1. Set security headers using Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year in seconds
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Configure CORS properly - restrict to trusted origins in production
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' ? ['https://yourdomain.com'] : ['http://localhost:3000'],
  optionsSuccessStatus: 200,
  credentials: true, // Allow cookies if needed
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// 3. Rate limiting to prevent brute-force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skipSuccessfulRequests: false, // Count all requests
  keyGenerator: (req) => {
    // Use IP address or API key if available
    return req.ip || req.headers['x-api-key'];
  }
});

// Apply rate limiting to all requests
app.use(limiter);

// 4. Request logging (use 'combined' for production, 'dev' for development)
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// ==================== REQUEST PROCESSING MIDDLEWARE ====================

// JSON body parsing with size limit
app.use(express.json({
  limit: '10kb' // Prevent large payload attacks
}));

// URL-encoded body parsing with size limit
app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// ==================== ERROR HANDLING MIDDLEWARE ====================

// Centralized error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled Error:', err);

  // Don't leak stack traces in production
  const errorResponse = {
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' 
      ? 'An unexpected error occurred' 
      : err.message,
    statusCode: 500
  };

  res.status(500).json(errorResponse);
});

// Not found middleware
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    statusCode: 404
  });
});

// ==================== ROUTES WITH VALIDATION ====================

// Health check endpoint
app.get('/health', [
  query('detailed')
    .optional()
    .isBoolean()
    .withMessage('detailed must be a boolean')
    .toBoolean(),
], (req, res) => {
  // Validate inputs
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array(),
      statusCode: 400 
    });
  }

  try {
    const { detailed } = req.query;
    const healthData = {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };

    res.json({
      status: 'ok',
      data: detailed ? healthData : { 
        status: 'healthy', 
        timestamp: healthData.timestamp 
      },
      statusCode: 200
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Failed to process health check',
      statusCode: 500
    });
  }
});

// Users endpoint with validation
app.get('/users', [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be an integer between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('offset must be a non-negative integer')
    .toInt(),
  query('active')
    .optional()
    .isBoolean()
    .withMessage('active must be a boolean')
    .toBoolean(),
], (req, res) => {
  // Validate inputs
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array(),
      statusCode: 400 
    });
  }

  try {
    const { limit = 10, offset = 0, active } = req.query;

    // Sample user data (in real app, this would come from a database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', active: true },
      { id: 2, name: 'Bob', email: 'bob@example.com', active: true },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', active: false },
      { id: 4, name: 'Diana', email: 'diana@example.com', active: true },
      { id: 5, name: 'Eve', email: 'eve@example.com', active: false },
    ];

    // Filter users if active status is specified
    let filteredUsers = allUsers;
    if (typeof active === 'boolean') {
      filteredUsers = allUsers.filter(user => user.active === active);
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: filteredUsers.length,
        limit,
        offset,
        hasMore: offset + limit < filteredUsers.length
      },
      statusCode: 200
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Failed to retrieve users',
      statusCode: 500
    });
  }
});

