// Enhanced application with comprehensive error handling and input validation
// Security best practices implemented

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const hpp = require('hpp');
const cors = require('cors');
const { body, query, validationResult } = require('express-validator');
const Joi = require('joi');
const winston = require('winston');
const morgan = require('morgan');

// Initialize express app
const app = express();

// Security middleware setup
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// Prevent HTTP Parameter Pollution
app.use(hpp());

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

// Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again after 15 minutes',
  standardHeaders: true,
  legacyHeaders: false,
  skipSuccessfulRequests: false,
  keyGenerator: (req) => {
    return req.ip || req.headers['x-forwarded-for'] || req.connection.remoteAddress;
  }
});

app.use('/api/', apiLimiter);

// JSON parsing with size limit
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// Request logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    new winston.transports.Console({
      format: winston.format.simple()
    })
  ]
});

// Morgan logging middleware
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim())
  }
}));

// Environment validation
const validateEnvironment = () => {
  const requiredEnvVars = [];

  requiredEnvVars.forEach(envVar => {
    if (!process.env[envVar]) {
      logger.error(`Missing required environment variable: ${envVar}`);
      throw new Error(`Missing required environment variable: ${envVar}`);
    }
  });

  // Validate NODE_ENV
  const validEnvs = ['development', 'production', 'test'];
  if (!validEnvs.includes(process.env.NODE_ENV)) {
    logger.warn(`Invalid NODE_ENV: ${process.env.NODE_ENV}. Defaulting to development`);
    process.env.NODE_ENV = 'development';
  }
};

// Validate environment on startup
try {
  validateEnvironment();
} catch (error) {
  logger.error(`Environment validation failed: ${error.message}`);
  process.exit(1);
}

// Global error handling middleware
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('User-Agent')
  });

  // Don't expose sensitive error details in production
  const responseError = process.env.NODE_ENV === 'production' 
    ? 'An unexpected error occurred' 
    : err.message;

  res.status(err.status || 500).json({
    error: responseError,
    requestId: req.id || Date.now().toString(36)
  });
});

// Custom middleware for input validation error handling
const validate = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (errors.isEmpty()) {
      return next();
    }

    logger.warn({
      message: 'Validation failed',
      errors: errors.array(),
      url: req.url,
      method: req.method
    });

    res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        param: err.param,
        msg: err.msg,
        location: err.location
      }))
    });
  };
};

// Input sanitization middleware
const sanitizeInput = (req, res, next) => {
  const sanitize = (obj) => {
    if (typeof obj === 'string') {
      // Remove potentially dangerous characters
      return obj.replace(/[<>]/g, '').trim();
    }
    if (typeof obj === 'object' && obj !== null) {
      Object.keys(obj).forEach(key => {
        obj[key] = sanitize(obj[key]);
      });
    }
    return obj;
  };

  if (req.body) req.body = sanitize(req.body);
  if (req.query) req.query = sanitize(req.query);
  if (req.params) req.params = sanitize(req.params);

  next();
};

// Joi validation schemas
const userSchema = Joi.object({
  name: Joi.string()
    .min(2)
    .max(50)
    .required()
    .pattern(/^[a-zA-Z\s]+$/)
    .messages({
      'string.pattern.base': 'Name can only contain letters and spaces',
      'string.min': 'Name must be at least 2 characters',
      'string.max': 'Name cannot exceed 50 characters'
    }),
  email: Joi.string()
    .email()
    .required()
    .messages({
      'string.email': 'Invalid email format'
    }),
  id: Joi.number()
    .integer()
    .positive()
    .optional()
});

// Health check endpoint with validation
app.get('/health', [
  query('detailed').optional().isBoolean().withMessage('detailed must be a boolean')
], validate, sanitizeInput, (req, res) => {
  try {
    const detailed = req.query.detailed === 'true';
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    if (detailed) {
      healthData.memory = process.memoryUsage();
      healthData.nodeVersion = process.version;
    }

    res.json(healthData);
  } catch (error) {
    logger.error(`Health check failed: ${error.message}`);
    res.status(500).json({ 
      status: 'error', 
      message: 'Health check failed',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with comprehensive validation
app.get('/users', [
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
  query('sort').optional().isIn(['name', 'email', 'id']).withMessage('Invalid sort field')
], validate, sanitizeInput, async (req, res, next) => {
  try {
    const { limit = 10, offset = 0, sort = 'id' } = req.query;

    // Simulate database query with validation
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Validate users data matches schema
    users.forEach(user => {
      const { error } = userSchema.validate(user);
      if (error) {
        throw new Error(`Invalid user data: ${error.details.map(d => d.message).join(', ')}`);
      }
    });

    // Apply sorting
    const sortedUsers = [...users].sort((a, b) => {
      if (sort === 'name') return a.name.localeCompare(b.name);
      if (sort === 'email') return a.email.localeCompare(b.email);
      return a.id - b.id;
    });

    // Apply pagination
    const paginatedUsers = sortedUsers.slice(offset, offset + parseInt(limit));

    res.json({
      data: paginatedUsers,
      pagination: {
        total: users.length,
        limit: parseInt(limit),
        offset: parseInt(offset),
        hasMore: offset + parseInt(limit) < users.length
      }
    });
  } catch (error) {
    next(error); // Pass to error handling middleware
  }
});

// Example POST endpoint with validation
app.post('/users', [
  body('name')
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 50 }).withMessage('Name must be 2-50 characters')
    .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces'),
  body('email')
    .notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Invalid email format')
    .normalizeEmail(),
  body('age')
    .optional()
    .isInt({ min: 0, max: 120 }).withMessage('Age must be between 0 and 120')
], validate, sanitizeInput, async (req, res, next) => {
  try {
    const { name, email, age } = req.body;

    // Additional business logic validation
    if (email.includes('example.com')) {
      logger.warn(`Attempted to create user with example.com email: ${email}`);
      return res.status(400).json({
        error: 'Please use a valid email address'
      });
    }

    // Simulate user creation
    const newUser = {
      id: Date.now(),
      name,
      email,
      ...(age && { age }),
      createdAt: new Date().toISOString()
    };

    // Log successful user creation
    logger.info(`User created: ${email}`);

    res.status(201).json({
      message: 'User created successfully',
      data: newUser
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler
app.use('*', (req, res) => {
  logger.warn(`404 Not Found: ${req.method} ${req.originalUrl}`);
  res.status(404).json({
    error: 'Endpoint not found',
    path: req.originalUrl,
    method: req.method
  });
});

// Global unhandled rejection handler
process.on('unhandledRejection', (reason, promise) => {
  logger.error(`Unhandled Rejection at: ${promise}, reason: ${reason}`);
  // In production, you might want to exit and restart
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// Global uncaught exception handler
process.on('uncaughtException', (error) => {
  logger.error(`Uncaught Exception: ${error.message}`, error.stack);
  // In production, you might want to exit and restart
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// Graceful shutdown handler
const gracefulShutdown = () => {
  logger.info('Received shutdown signal, starting graceful shutdown');

  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    logger.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

// Listen for shutdown signals
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV} mode`);
});

module.exports = app;

// Enhanced application with essential error handling and input validation
const express = require('express');
const app = express();

// Basic security middleware
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// Basic request logging
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.url} - IP: ${req.ip}`);
  next();
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error(`Error: ${err.message}`, err.stack);

  // Don't expose internal errors in production
  const errorMessage = process.env.NODE_ENV === 'production' 
    ? 'An error occurred' 
    : err.message;

  res.status(err.status || 500).json({ 
    error: errorMessage,
    timestamp: new Date().toISOString()
  });
});

// Basic input sanitization
const sanitizeInput = (req, res, next) => {
  const sanitize = (obj) => {
    if (typeof obj === 'string') {
      // Basic XSS protection
      return obj.replace(/[<>]/g, '').trim();
    }
    if (typeof obj === 'object' && obj !== null) {
      for (const key in obj) {
        if (obj.hasOwnProperty(key)) {
          obj[key] = sanitize(obj[key]);
        }
      }
    }
    return obj;
  };

  if (req.body) req.body = sanitize(req.body);
  if (req.query) req.query = sanitize(req.query);

  next();
};

// Health check with validation
app.get('/health', sanitizeInput, (req, res) => {
  try {
    // Validate query parameters
    const { detailed } = req.query;
    if (detailed && detailed !== 'true' && detailed !== 'false') {
      throw new Error('detailed parameter must be "true" or "false"');
    }

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString()
    };

    if (detailed === 'true') {
      response.uptime = process.uptime();
      response.memory = process.memoryUsage();
    }

    res.json(response);
  } catch (error) {
    error.status = 400; // Bad Request
    next(error);
  }
});

// Users endpoint with validation
app.get('/users', sanitizeInput, (req, res, next) => {
  try {
    // Validate query parameters
    const { limit, offset } = req.query;

    if (limit && !/^\d+$/.test(limit)) {
      throw new Error('limit must be a positive integer');
    }

    if (offset && !/^\d+$/.test(offset)) {
      throw new Error('offset must be a positive integer');
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Basic data validation
    users.forEach(user => {
      if (!user.id || !user.name || !user.email) {
        throw new Error('Invalid user data structure');
      }

      // Email format validation
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(user.email)) {
        throw new Error(`Invalid email format for user: ${user.name}`);
      }
    });

    res.json(users);
  } catch (error) {
    error.status = error.status || 400;
    next(error);
  }
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Endpoint not found',
    path: req.originalUrl
  });
});

// Start server with error handling
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle server errors
server.on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use`);
    process.exit(1);
  } else {
    console.error('Server error:', error);
  }
});

// Graceful shutdown
const gracefulShutdown = () => {
  console.log('Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  setTimeout(() => {
    console.error('Forcing shutdown...');
    process.exit(1);
  }, 5000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

module.exports = app;

