// Improved application with comprehensive error handling and input validation
// Security best practices implementation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult, query, param } = require('express-validator');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
}));

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use('/api/', limiter);

// Body parsing middleware with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  const originalSend = res.send;
  res.send = function(data) {
    const duration = Date.now() - start;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl} ${res.statusCode} ${duration}ms`);
    return originalSend.call(this, data);
  };
  next();
});

// Error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error(`[ERROR][${new Date().toISOString()}] ${err.stack}`);

  // Don't expose internal error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' && statusCode === 500 
    ? 'Internal Server Error' 
    : err.message;

  res.status(statusCode).json({
    error: {
      message: message,
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
    }
  });
};

app.use(errorHandler);

// Input validation middleware
const validateRequest = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (errors.isEmpty()) {
      return next();
    }

    console.warn(`[VALIDATION_ERROR][${new Date().toISOString()}] ${req.method} ${req.originalUrl}`, errors.array());
    return res.status(400).json({
      error: {
        message: 'Validation failed',
        details: errors.array()
      }
    });
  };
};

// Health endpoint with validation
app.get('/health', validateRequest([
  query('verbose').optional().isBoolean().withMessage('verbose must be a boolean')
]), (req, res, next) => {
  try {
    const verbose = req.query.verbose === 'true';
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
    };

    if (verbose) {
      healthData.system = {
        platform: process.platform,
        nodeVersion: process.version,
      };
    }

    res.status(200).json(healthData);
  } catch (error) {
    next(new Error('Failed to retrieve health status'));
  }
});

// Users endpoint with comprehensive input validation
app.get('/users', validateRequest([
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('offset must be a positive integer'),
  query('search').optional().isLength({ max: 50 }).withMessage('search query too long')
    .matches(/^[a-zA-Z0-9\s]*$/).withMessage('search can only contain alphanumeric characters and spaces'),
]), async (req, res, next) => {
  try {
    const { limit = 10, offset = 0, search = '' } = req.query;

    // Mock user data (in real application, this would come from a database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'user' },
      { id: 4, name: 'Diana', email: 'diana@example.com', role: 'moderator' },
    ];

    // Filter users based on search parameter (safely)
    const filteredUsers = search ? allUsers.filter(user => 
      user.name.toLowerCase().includes(search.toLowerCase()) ||
      user.email.toLowerCase().includes(search.toLowerCase())
    ) : allUsers;

    // Apply pagination
    const users = filteredUsers.slice(parseInt(offset), parseInt(offset) + parseInt(limit));

    res.json({
      data: users,
      pagination: {
        total: filteredUsers.length,
        limit: parseInt(limit),
        offset: parseInt(offset),
        hasMore: (parseInt(offset) + parseInt(limit)) < filteredUsers.length
      }
    });

  } catch (error) {
    console.error(`[USER_ERROR][${new Date().toISOString()}] ${error.message}`);
    next(new Error('Failed to retrieve users'));
  }
});

// User creation endpoint with validation
app.post('/users', validateRequest([
  body('name').trim().notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
    .matches(/^[a-zA-Z\s]*$/).withMessage('Name can only contain letters and spaces'),
  body('email').trim().notEmpty().withMessage('Email is required')
    .isEmail().normalizeEmail().withMessage('Valid email is required')
    .isLength({ max: 100 }).withMessage('Email too long'),
  body('role').optional().isIn(['user', 'admin', 'moderator']).withMessage('Invalid role'),
]), async (req, res, next) => {
  try {
    const { name, email, role = 'user' } = req.body;

    // Sanitize inputs further (express-validator does basic sanitization)
    const sanitizedName = name.replace(/[<>]/g, ''); // Remove potential HTML tags
    const sanitizedEmail = email.toLowerCase(); // Normalize email

    // In a real application, you would:
    // 1. Check if email already exists
    // 2. Hash password (not shown here)
    // 3. Save to database

    const newUser = {
      id: Date.now(), // Temporary ID - would be generated by database
      name: sanitizedName,
      email: sanitizedEmail,
      role: role,
      createdAt: new Date().toISOString()
    };

    // Simulate database save
    console.log(`[USER_CREATED][${new Date().toISOString()}] User created: ${sanitizedEmail}`);

    res.status(201).json({
      message: 'User created successfully',
      data: newUser
    });

  } catch (error) {
    console.error(`[USER_CREATION_ERROR][${new Date().toISOString()}] ${error.message}`);
    next(new Error('Failed to create user'));
  }
});

// User detail endpoint with parameter validation
app.get('/users/:id', validateRequest([
  param('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer')
]), async (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);

    // Mock database lookup
    const user = { id: 1, name: 'Alice', email: 'alice@example.com' };

    if (!user || user.id !== userId) {
      return res.status(404).json({ 
        error: { message: 'User not found' } 
      });
    }

    res.json({ data: user });

  } catch (error) {
    console.error(`[USER_DETAIL_ERROR][${new Date().toISOString()}] ${error.message}`);
    next(new Error('Failed to retrieve user details'));
  }
});

// Global catch-all for unknown routes
app.all('*', (req, res, next) => {
  next(new Error(`Route ${req.originalUrl} not found`));
  res.status(404).json({
    error: {
      message: 'Route not found'
    }
  });
});

// Server startup with graceful shutdown handling
const server = app.listen(3000, () => {
  console.log(`[${new Date().toISOString()}] Server running on port 3000`);
});

// Graceful shutdown handlers
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

function gracefulShutdown(signal) {
  console.log(`[${new Date().toISOString()}] Received ${signal}, starting graceful shutdown...`);

  server.close(() => {
    console.log(`[${new Date().toISOString()}] HTTP server closed`);

    // Close database connections, etc. here
    console.log(`[${new Date().toISOString()}] Graceful shutdown complete`);
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.log(`[${new Date().toISOString()}] Forcing shutdown after timeout`);
    process.exit(1);
  }, 10000);
}

module.exports = app;

