// Enhanced application with security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
const dotenv = require('dotenv');

// Load environment variables
dotenv.config();

const app = express();

// ========================
// Security Middleware Setup
// ========================

// 1. Set security headers using Helmet
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            scriptSrc: ["'self'", "'unsafe-inline'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            imgSrc: ["'self'", "data:", "https:"],
            connectSrc: ["'self'"],
            fontSrc: ["'self'"],
            objectSrc: ["'none'"],
            mediaSrc: ["'self'"],
            frameSrc: ["'none'"]
        }
    },
    crossOriginEmbedderPolicy: false // disable for certain APIs if needed
}));

// 2. Enable CORS with specific origin (adjust as needed)
const allowedOrigins = process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'];
app.use(cors({
    origin: function(origin, callback) {
        // Allow requests with no origin (like mobile apps or curl requests)
        if (!origin) return callback(null, true);

        if (allowedOrigins.indexOf(origin) === -1) {
            const msg = 'The CORS policy for this site does not allow access from the specified origin.';
            return callback(new Error(msg), false);
        }
        return callback(null, true);
    },
    credentials: true
}));

// 3. Request parsing with limits
app.use(express.json({ limit: '10kb' })); // Prevent large JSON payloads
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 4. Request logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// 5. Rate limiting
const apiLimiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false
});

// Apply rate limiting to all routes
app.use(apiLimiter);

// ========================
// Custom Middleware
// ========================

// Input validation error handler
const validateInput = (validations) => {
    return async (req, res, next) => {
        await Promise.all(validations.map(validation => validation.run(req)));

        const errors = validationResult(req);
        if (errors.isEmpty()) {
            return next();
        }

        return res.status(400).json({
            success: false,
            errors: errors.array().map(err => ({
                field: err.param,
                message: err.msg,
                value: err.value
            }))
        });
    };
};

// Global error handler
const errorHandler = (err, req, res, next) => {
    console.error(`[${new Date().toISOString()}] Error:`, {
        message: err.message,
        stack: err.stack,
        path: req.path,
        method: req.method
    });

    // Don't leak stack traces in production
    const isProduction = process.env.NODE_ENV === 'production';

    res.status(err.status || 500).json({
        success: false,
        message: isProduction ? 'Internal server error' : err.message,
        ...(isProduction ? {} : { stack: err.stack })
    });
};

// Async handler wrapper to catch async errors
const asyncHandler = (fn) => (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
};

// ========================
// Routes with Input Validation
// ========================

app.get('/health', asyncHandler(async (req, res) => {
    res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        uptime: process.uptime()
    });
}));

// Parameter validation for user endpoints
app.get('/users', 
    validateInput([
        query('limit')
            .optional()
            .isInt({ min: 1, max: 100 })
            .withMessage('Limit must be between 1 and 100'),
        query('page')
            .optional()
            .isInt({ min: 1 })
            .withMessage('Page must be a positive integer'),
        query('search')
            .optional()
            .isString()
            .trim()
            .escape() // Escape HTML entities to prevent XSS
            .isLength({ max: 100 })
            .withMessage('Search term cannot exceed 100 characters')
    ]),
    asyncHandler(async (req, res) => {
        const { limit = 10, page = 1, search } = req.query;

        // Sanitize and validate further if needed
        const sanitizedSearch = search ? search.replace(/[<>]/g, '') : null;

        // Dummy data - in real app, this would come from a database
        const users = [
            { 
                id: 1, 
                name: 'Alice', 
                email: 'alice@example.com',
                age: 30,
                createdAt: '2023-01-01T00:00:00Z'
            },
            { 
                id: 2, 
                name: 'Bob', 
                email: 'bob@example.com',
                age: 25,
                createdAt: '2023-01-02T00:00:00Z'
            },
        ];

        // Filter based on search if provided
        const filteredUsers = sanitizedSearch
            ? users.filter(user => 
                user.name.toLowerCase().includes(sanitizedSearch.toLowerCase()) ||
                user.email.toLowerCase().includes(sanitizedSearch.toLowerCase())
            )
            : users;

        // Paginate results
        const startIndex = (page - 1) * limit;
        const endIndex = startIndex + parseInt(limit);
        const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

        res.json({
            success: true,
            data: {
                users: paginatedUsers,
                pagination: {
                    total: filteredUsers.length,
                    page: parseInt(page),
                    limit: parseInt(limit),
                    pages: Math.ceil(filteredUsers.length / limit)
                }
            }
        });
    })
);

// Example POST endpoint with input validation
app.post('/users',
    validateInput([
