            .notEmpty().withMessage('Name is required')
            .isString().withMessage('Name must be a string')
            .trim()
            .escape()
            .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
            .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces'),
        body('email')
            .notEmpty().withMessage('Email is required')
            .isEmail().withMessage('Invalid email format')
            .normalizeEmail(),
        body('age')
            .optional()
            .isInt({ min: 0, max: 120 }).withMessage('Age must be between 0 and 120')
    ]),
    asyncHandler(async (req, res) => {
        const { name, email, age } = req.body;

        // In a real app, you would:
        // 1. Check if email already exists
        // 2. Hash password if provided
        // 3. Save to database

        const newUser = {
            id: Date.now(), // Temporary ID
            name,
            email,
            age: age || null,
            createdAt: new Date().toISOString()
        };

        res.status(201).json({
            success: true,
            message: 'User created successfully',
            data: newUser
        });
    })
);

// Get user by ID with validation
app.get('/users/:id',
    validateInput([
        query('id')
            .isInt({ min: 1 }).withMessage('User ID must be a positive integer')
    ]),
    asyncHandler(async (req, res) => {
        const userId = parseInt(req.params.id);

        // Validate user ID
        if (isNaN(userId) || userId <= 0) {
            return res.status(400).json({
                success: false,
                message: 'Invalid user ID'
            });
        }

        // Dummy data lookup
        const users = [
            { id: 1, name: 'Alice', email: 'alice@example.com' },
            { id: 2, name: 'Bob', email: 'bob@example.com' },
        ];

        const user = users.find(u => u.id === userId);

        if (!user) {
            return res.status(404).json({
                success: false,
                message: 'User not found'
            });
        }

        res.json({
            success: true,
            data: user
        });
    })
);

// ========================
// Not Found Handler
// ========================

app.use('*', (req, res) => {
    res.status(404).json({
        success: false,
        message: `Route ${req.originalUrl} not found`
    });
});

// ========================
// Error Handling Middleware
// ========================

app.use(errorHandler);

// ========================
// Server Setup with Graceful Shutdown
// ========================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

const server = app.listen(PORT, HOST, () => {
    console.log(`Server running on http://${HOST}:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
    console.log('Security middleware enabled: Helmet, CORS, Rate limiting');
});

// Graceful shutdown
const gracefulShutdown = (signal) => {
    console.log(`\nReceived ${signal}. Starting graceful shutdown...`);

    server.close(() => {
        console.log('HTTP server closed');

        // Close database connections, cleanup tasks, etc.
        console.log('Cleanup tasks completed');
        process.exit(0);
    });

    // Force shutdown after timeout
    setTimeout(() => {
        console.error('Could not close connections in time, forcefully shutting down');
        process.exit(1);
    }, 10000);
};

// Handle termination signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle unhandled rejections
process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    // In production, you might want to log to an external service
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
    console.error('Uncaught Exception:', error);
    // In production, you might want to restart the process after cleanup
    process.exit(1);
});

module.exports = {
    app,
    server
};

