// Minimal secure version with essential improvements

const express = require('express');

const app = express();

// ========================
// Security Middleware
// ========================

// Basic security headers
app.use((req, res, next) => {
    // Prevent MIME sniffing
    res.setHeader('X-Content-Type-Options', 'nosniff');
    // Prevent clickjacking
    res.setHeader('X-Frame-Options', 'DENY');
    // Basic XSS protection
    res.setHeader('X-XSS-Protection', '1; mode=block');
    // Remove X-Powered-By header
    res.removeHeader('X-Powered-By');
    next();
});

// Request body parsing with size limit
app.use(express.json({ limit: '10kb' }));

// ========================
// Input Validation Utilities
// ========================

const validateQueryParams = (req, res, next) => {
    // Example validation for /users endpoint
    if (req.path === '/users') {
        const { limit, page, search } = req.query;

        // Validate limit if provided
        if (limit && (!Number.isInteger(Number(limit)) || Number(limit) < 1 || Number(limit) > 100)) {
            return res.status(400).json({
                error: 'Invalid parameter',
                message: 'Limit must be an integer between 1 and 100'
            });
        }

        // Validate page if provided
        if (page && (!Number.isInteger(Number(page)) || Number(page) < 1)) {
            return res.status(400).json({
                error: 'Invalid parameter',
                message: 'Page must be a positive integer'
            });
        }

        // Sanitize search term to prevent XSS
        if (search && typeof search === 'string') {
            // Basic HTML escaping
            req.query.search = search
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&#x27;');
        }
    }
    next();
};

app.use(validateQueryParams);

// ========================
// Error Handling Middleware
// ========================

const errorHandler = (err, req, res, next) => {
    console.error('Error:', err.message);

    // Determine appropriate status code
    const statusCode = err.statusCode || 500;

    // Don't expose stack traces in production
    const errorResponse = {
        error: 'Internal Server Error',
        message: process.env.NODE_ENV === 'production' 
            ? 'An error occurred' 
            : err.message
    };

    res.status(statusCode).json(errorResponse);
};

// Async error handler wrapper
const asyncHandler = (fn) => {
    return (req, res, next) => {
        Promise.resolve(fn(req, res, next)).catch(next);
    };
};

// ========================
// Routes with Improved Error Handling
// ========================

app.get('/health', asyncHandler(async (req, res) => {
    try {
        res.json({ 
            status: 'ok', 
            timestamp: new Date().toISOString() 
        });
    } catch (error) {
        // Log error and pass to error handler
        console.error('Health check error:', error);
        throw error;
    }
}));

app.get('/users', asyncHandler(async (req, res) => {
    try {
        const { limit = 10, page = 1, search } = req.query;

        // Example data - in real app would come from database
        const users = [
            { id: 1, name: 'Alice', email: 'alice@example.com' },
            { id: 2, name: 'Bob', email: 'bob@example.com' },
        ];

        // Filter based on search if provided
        let filteredUsers = users;
        if (search) {
            filteredUsers = users.filter(user => 
                user.name.toLowerCase().includes(search.toLowerCase()) ||
                user.email.toLowerCase().includes(search.toLowerCase())
            );
        }

        // Pagination
        const pageNum = parseInt(page);
        const limitNum = parseInt(limit);
        const startIndex = (pageNum - 1) * limitNum;
        const endIndex = startIndex + limitNum;
        const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

        res.json({
            data: paginatedUsers,
            pagination: {
                total: filteredUsers.length,
                page: pageNum,
                limit: limitNum,
                totalPages: Math.ceil(filteredUsers.length / limitNum)
            }
        });
    } catch (error) {
        console.error('Users endpoint error:', error);
        throw error;
    }
}));

// 404 handler
app.use((req, res) => {
    res.status(404).json({
        error: 'Not Found',
        message: `Route ${req.originalUrl} not found`
    });
});

// Global error handler
app.use(errorHandler);

// ========================
// Server Configuration
// ========================

// Configurable port with fallback
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

const server = app.listen(PORT, HOST, () => {
    console.log(`Server running on http://${HOST}:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
    console.log('SIGTERM received, shutting down gracefully');
    server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
    });
});

process.on('SIGINT', () => {
    console.log('SIGINT received, shutting down gracefully');
    server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
    });
});

module.exports = app;

