// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const compression = require('compression');

const app = express();

// ========== Step 1: Configure Security Middleware ==========

// 1.1 Helmet for security headers
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:", "https:"],
            connectSrc: ["'self'"]
        }
    },
    hsts: {
        maxAge: 31536000, // 1 year
        includeSubDomains: true,
        preload: true
    }
}));

// 1.2 Configure CORS securely
app.use(cors({
    origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3001'],
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization']
}));

// 1.3 Rate limiting to prevent DoS attacks
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: {
        error: 'Too many requests from this IP, please try again later.'
    },
    standardHeaders: true,
    legacyHeaders: false
});

app.use(limiter);

// 1.4 Compression for performance
app.use(compression());

// ========== Step 2: Configure Application Middleware ==========

// 2.1 Body parsing with size limits
app.use(express.json({
    limit: '10kb' // Prevent large payload attacks
}));

app.use(express.urlencoded({
    extended: true,
    limit: '10kb'
}));

// 2.2 Request logging middleware
const requestLogger = (req, res, next) => {
    const start = Date.now();

    // Log after response is sent
    res.on('finish', () => {
        const duration = Date.now() - start;
        console.log({
            timestamp: new Date().toISOString(),
            method: req.method,
            url: req.originalUrl,
            status: res.statusCode,
            duration: `${duration}ms`,
            userAgent: req.get('User-Agent'),
            ip: req.ip
        });
    });

    next();
};

app.use(requestLogger);

// ========== Step 3: Input Validation Functions ==========

/**
 * Validate and sanitize user ID
 * @param {string|number} id - User ID to validate
 * @returns {number|null} - Validated ID or null if invalid
 */
const validateUserId = (id) => {
    if (id === undefined || id === null) return null;

    // Convert to number and validate
    const numId = Number(id);

    if (isNaN(numId) || !Number.isInteger(numId) || numId <= 0) {
        return null;
    }

    // Ensure it's within reasonable bounds
    if (numId > 999999) {
        return null; // Prevent large number attacks
    }

    return numId;
};

/**
 * Validate query parameters
 * @param {Object} query - Query parameters object
 * @returns {Object} - Validated and sanitized parameters
 */
const validateQueryParams = (query) => {
    const result = {};

    // Validate limit parameter
    if (query.limit) {
        const limit = Number(query.limit);
        if (!isNaN(limit) && Number.isInteger(limit) && limit > 0 && limit <= 100) {
            result.limit = limit;
        } else {
            result.limit = 10; // Default
        }
    } else {
        result.limit = 10;
    }

    // Validate page parameter
    if (query.page) {
        const page = Number(query.page);
        if (!isNaN(page) && Number.isInteger(page) && page >= 1) {
            result.page = page;
        } else {
            result.page = 1; // Default
        }
    } else {
        result.page = 1;
    }

    return result;
};

// ========== Step 4: Route Definitions with Error Handling ==========

app.get('/health', (req, res) => {
    try {
        res.json({
            status: 'ok',
            timestamp: new Date().toISOString(),
            uptime: process.uptime(),
            memory: process.memoryUsage()
        });
    } catch (error) {
        console.error('Health check error:', error);
        res.status(500).json({
            error: 'Internal server error',
            timestamp: new Date().toISOString()
        });
    }
});

app.get('/users', (req, res) => {
    try {
        // Validate query parameters
        const { limit, page } = validateQueryParams(req.query);

        // Mock user data - in real app, this would come from a database
        const mockUsers = [
            { id: 1, name: 'Alice', email: 'alice@example.com' },
            { id: 2, name: 'Bob', email: 'bob@example.com' },
            { id: 3, name: 'Charlie', email: 'charlie@example.com' },
            { id: 4, name: 'Diana', email: 'diana@example.com' }
        ];

        // Calculate pagination
        const startIndex = (page - 1) * limit;
        const endIndex = startIndex + limit;
        const paginatedUsers = mockUsers.slice(startIndex, endIndex);

        res.json({
            users: paginatedUsers,
            pagination: {
                currentPage: page,
                pageSize: limit,
                totalItems: mockUsers.length,
                totalPages: Math.ceil(mockUsers.length / limit)
            }
        });
    } catch (error) {
        console.error('Error fetching users:', error);
        res.status(500).json({
            error: 'Failed to fetch users',
            message: 'An internal error occurred'
        });
    }
});

app.get('/users/:id', (req, res) => {
    try {
        const userId = validateUserId(req.params.id);

        if (!userId) {
            return res.status(400).json({
                error: 'Invalid user ID',
                message: 'User ID must be a positive integer'
            });
        }

        // Mock data - in real app, fetch from database
        const mockUser = [
            { id: 1, name: 'Alice', email: 'alice@example.com' },
            { id: 2, name: 'Bob', email: 'bob@example.com' }
        ].find(user => user.id === userId);

        if (!mockUser) {
            return res.status(404).json({
                error: 'User not found',
                message: `User with ID ${userId} does not exist`
            });
        }

        res.json(mockUser);
    } catch (error) {
        console.error('Error fetching user:', error);
        res.status(500).json({
            error: 'Failed to fetch user',
            message: 'An internal error occurred'
        });
    }
});

// ========== Step 5: Error Handling Middleware ==========

// 5.1 404 Not Found handler
app.use('*', (req, res) => {
    res.status(404).json({
        error: 'Not Found',
        message: `Route ${req.originalUrl} not found`,
        timestamp: new Date().toISOString()
    });
});

// 5.2 Global error handler
app.use((err, req, res, next) => {
    console.error('Unhandled error:', {
        error: err.message,
        stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
        url: req.originalUrl,
        method: req.method,
        ip: req.ip
    });

    // Don't expose internal errors to client
    const clientMessage = process.env.NODE_ENV === 'development' 
        ? err.message 
        : 'Internal server error';

    res.status(err.status || 500).json({
        error: 'Internal Server Error',
        message: clientMessage,
        timestamp: new Date().toISOString()
    });
});

// ========== Step 6: Server Initialization with Validation ==========

// Validate required environment variables
const validateEnvironment = () => {
    const requiredEnvVars = [];

    if (!process.env.NODE_ENV) {
        console.warn('NODE_ENV not set, defaulting to development');
        process.env.NODE_ENV = 'development';
    }

    // In production, validate required variables
    if (process.env.NODE_ENV === 'production') {
        requiredEnvVars.push('PORT', 'ALLOWED_ORIGINS');
    }

    const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);

    if (missingVars.length > 0) {
        console.error('Missing required environment variables:', missingVars);
        process.exit(1);
    }
};

// Graceful shutdown handling
const setupGracefulShutdown = (server) => {
    const shutdown = async (signal) => {
        console.log(`Received ${signal}, shutting down gracefully...`);

        server.close(() => {
            console.log('HTTP server closed');
            process.exit(0);
        });

        // Force shutdown after 10 seconds
        setTimeout(() => {
            console.error('Could not close connections in time, forcefully shutting down');
            process.exit(1);
        }, 10000);
    };

    process.on('SIGTERM', () => shutdown('SIGTERM'));
    process.on('SIGINT', () => shutdown('SIGINT'));
};

const startServer = () => {
    try {
        validateEnvironment();

        const PORT = process.env.PORT || 3000;
        const server = app.listen(PORT, () => {
            console.log({
                message: `Server running on port ${PORT}`,
                environment: process.env.NODE_ENV,
                timestamp: new Date().toISOString(),
                pid: process.pid
            });
        });

        setupGracefulShutdown(server);

        return server;
    } catch (error) {
        console.error('Failed to start server:', error);
        process.exit(1);
    }
};

// Start server if this file is run directly
if (require.main === module) {
    startServer();
}

module.exports = {
    app,
    startServer,
    validateUserId,
    validateQueryParams
};

