# Security Review and Improvement Suggestions for app.js

## Current State Analysis

The current `app.js` is a minimal Express.js application with:
1. A `/health` endpoint returning JSON status
2. A `/users` endpoint returning static user data
3. No error handling
4. No input validation
5. No security headers
6. Basic console logging

## Critical Security Issues Identified

### 1. **No Error Handling**
   - The application has no try-catch blocks
   - No error middleware for unhandled exceptions
   - No graceful shutdown handling
   - No logging of errors

### 2. **No Input Validation/Sanitization**
   - No validation of query parameters
   - No request body validation (if endpoints are added)
   - No output sanitization
   - No rate limiting

### 3. **Missing Security Headers**
   - No Helmet.js integration for security headers
   - No CORS configuration
   - No Content Security Policy
   - No XSS protection headers

### 4. **Insecure Configuration**
   - Port hardcoded (3000)
   - No environment-based configuration
   - Sensitive data (user emails) exposed without authentication
   - No rate limiting

### 5. **Lack of Logging**
   - No structured logging
   - No audit logging
   - No security event logging

## Recommended Improvements

### 1. **Error Handling Implementation**

```javascript
// Add error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.url,
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  res.status(err.statusCode || 500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'development' ? err.message : undefined
  });
});

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({ error: 'Route not found' });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

### 2. **Input Validation Enhancement**

```javascript
const { body, query, validationResult } = require('express-validator');

// Add validation to /users endpoint
app.get('/users', [
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
], (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Existing logic here
  next();
}, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

### 3. **Security Headers and Middleware**

```javascript
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use('/api/', limiter);
```

### 4. **Environment-Based Configuration**

```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Remove sensitive data from logs
const morgan = require('morgan');
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev', {
  skip: (req, res) => {
    // Skip health checks from logs in production
    return req.url === '/health' && NODE_ENV === 'production';
  }
}));
```

### 5. **Enhanced Logging**

```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    ...(NODE_ENV === 'development' ? [new winston.transports.Console({
      format: winston.format.simple()
    })] : [])
  ]
});

// Request logging middleware
app.use((req, res, next) => {
  logger.info('HTTP request', {
    method: req.method,
    url: req.url,
    ip: req.ip,
    userAgent: req.get('User-Agent'),
    timestamp: new Date().toISOString()
  });
  next();
});
```

### 6. **Data Protection**

```javascript
// Mask sensitive data in responses
app.use((req, res, next) => {
  const originalJson = res.json;
  res.json = function(data) {
    if (Array.isArray(data)) {
      data = data.map(item => {
        if (item && typeof item === 'object') {
          const { email, ...rest } = item;
          // Only show masked email to unauthenticated users
          if (!req.headers.authorization && email) {
            return { 
              ...rest, 
              email: email.replace(/(.{2})(.*)(?=@)/, (match, start, middle) => 
                start + '*'.repeat(middle.length)
              )
            };
          }
        }
        return item;
      });
    }
    return originalJson.call(this, data);
  };
  next();
});
```

### 7. **Dependency Management**

Add to package.json:
```json
{
  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js",
    "test": "jest",
    "security-check": "npm audit && npx snyk test",
    "lint": "eslint ."
  },
  "dependencies": {
    "express": "^4.18.0",
    "helmet": "^7.0.0",
    "cors": "^2.8.5",
    "express-rate-limit": "^6.0.0",
    "express-validator": "^6.14.0",
    "winston": "^3.8.0",
    "morgan": "^1.10.0",
    "dotenv": "^16.0.0"
  },
  "devDependencies": {
    "eslint": "^8.0.0",
    "eslint-config-airbnb-base": "^15.0.0",
    "eslint-plugin-security": "^1.5.0",
    "jest": "^29.0.0",
    "supertest": "^6.0.0",
    "nodemon": "^2.0.0"
  }
}
```

## Implementation Priority

### **Critical (Should be implemented immediately)**
1. Add error handling middleware
2. Implement Helmet.js for security headers
3. Add environment-based configuration
4. Implement input validation for any new endpoints

### **Important (Implement in next revision)**
1. Add rate limiting
2. Implement structured logging
3. Add CORS configuration
4. Mask sensitive data in responses

### **Recommended (Good practices)**
1. Add request/response logging
2. Implement graceful shutdown
3. Add security headers
4. Create security test suite

## Testing Recommendations

1. **Security Testing:**
   - Run npm audit regularly
   - Use OWASP ZAP for vulnerability scanning
   - Implement security headers testing

2. **Input Validation Testing:**
   - Test with malformed inputs
   - Test SQL injection attempts
   - Test XSS payloads
   - Test path traversal attempts

3. **Error Handling Testing:**
   - Test unhandled exceptions
   - Test invalid routes
   - Test rate limiting
   - Test CORS violations

## Monitoring Recommendations

1. **Log monitoring for:**
   - 4xx and 5xx errors
   - Rate limit violations
   - Unusual request patterns
   - Failed authentication attempts

2. **Metrics to track:**
   - Request rate per endpoint
   - Error rate
   - Response time
   - Memory usage
   - CPU usage

This improved implementation provides defense-in-depth security, proper error handling, and follows security best practices for Node.js/Express applications.

// Secure Express.js application with enhanced error handling and security
// This version includes critical security improvements

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

// Load environment variables
require('dotenv').config();

// Initialize Express app
const app = express();

// Configuration
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS 
  ? process.env.ALLOWED_ORIGINS.split(',') 
  : ['http://localhost:3000', 'http://localhost:8080'];

// ======================================
// SECURITY MIDDLEWARE
// ======================================

// 1. Helmet.js for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'", "https:"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"]
    }
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  xssFilter: true,
  noSniff: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// 2. CORS configuration
app.use(cors({
  origin: (origin, callback) => {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin) return callback(null, true);

    if (ALLOWED_ORIGINS.indexOf(origin) === -1) {
      const msg = `The CORS policy for this site does not allow access from the specified Origin: ${origin}`;
      return callback(new Error(msg), false);
    }
    return callback(null, true);
  },
  credentials: false, // Set to true if using cookies/sessions
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'Accept'],
  exposedHeaders: ['Content-Length', 'X-Request-ID'],
  maxAge: 86400 // 24 hours
}));

// 3. Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes'
  },
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => req.url === '/health' // Skip health check from rate limiting
});

// Apply rate limiting to all routes
app.use(apiLimiter);

// ======================================
// REQUEST PARSING & VALIDATION
// ======================================

// Body parsing middleware with size limits
app.use(express.json({
  limit: '10kb', // Limit JSON body size to 10KB
  strict: true // Only accept arrays and objects
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
  parameterLimit: 10 // Limit number of parameters
}));

// Request logging middleware
app.use((req, res, next) => {
  const startTime = Date.now();

  // Log request details (sanitized)
  console.log(`${new Date().toISOString()} - ${req.method} ${req.url} - IP: ${req.ip} - User-Agent: ${req.get('User-Agent')?.substring(0, 50)}...`);

  // Add request ID for tracing
  req.requestId = Date.now().toString(36) + Math.random().toString(36).substr(2);

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    console.log(`${new Date().toISOString()} - Completed ${req.method} ${req.url} - Status: ${res.statusCode} - Duration: ${duration}ms`);
  });

  next();
});

// ======================================
// ROUTES WITH INPUT VALIDATION
// ======================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    const healthData = {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      environment: NODE_ENV
    };

    // Remove sensitive memory data in production
    if (NODE_ENV === 'production') {
      delete healthData.memory;
    }

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(503).json({
      status: 'unhealthy',
      error: 'Service unavailable',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with basic validation
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;
    const offset = req.query.offset ? parseInt(req.query.offset, 10) : 0;

    // Input validation
    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter',
        message: 'Limit must be a number between 1 and 100'
      });
    }

    if (isNaN(offset) || offset < 0) {
      return res.status(400).json({
        error: 'Invalid offset parameter',
        message: 'Offset must be a non-negative number'
      });
    }

    // Simulated user data (in production, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'admin' },
    ];

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    // Sanitize output based on user permissions
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name,
      // Only show full email for admins (based on auth token in real app)
      email: req.headers.authorization ? user.email : maskEmail(user.email)
    }));

    res.json({
      data: sanitizedUsers,
      pagination: {
        total: users.length,
        limit,
        offset,
        hasMore: offset + limit < users.length
      }
    });

  } catch (error) {
    next(error); // Pass error to error handling middleware
  }
});

// Helper function to mask email addresses
function maskEmail(email) {
  if (!email || !email.includes('@')) return email;

  const [localPart, domain] = email.split('@');
  if (localPart.length <= 2) {
    return `${'*'.repeat(localPart.length)}@${domain}`;
  }

  const maskedLocal = localPart.charAt(0) + '*'.repeat(localPart.length - 2) + localPart.charAt(localPart.length - 1);
  return `${maskedLocal}@${domain}`;
}

// ======================================
// ERROR HANDLING MIDDLEWARE
// ======================================

// 404 handler
app.use((req, res, next) => {
  const error = new Error(`Route not found: ${req.method} ${req.url}`);
  error.statusCode = 404;
  next(error);
});

// Global error handler
app.use((error, req, res, next) => {
  // Log error with request context
  console.error(`[${req.requestId || 'unknown'}] Error in ${req.method} ${req.url}:`, {
    message: error.message,
    stack: NODE_ENV === 'development' ? error.stack : undefined,
    statusCode: error.statusCode,
    timestamp: new Date().toISOString(),
    ip: req.ip,
    userAgent: req.get('User-Agent')
  });

  // Determine status code
  const statusCode = error.statusCode || 500;

  // Prepare error response
  const errorResponse = {
    error: getErrorMessage(statusCode),
    message: NODE_ENV === 'development' ? error.message : undefined,
    requestId: req.requestId,
    timestamp: new Date().toISOString()
  };

  // Add validation errors if present
  if (error.errors) {
    errorResponse.validationErrors = error.errors;
  }

  // Don't expose stack traces in production
  if (NODE_ENV === 'development' && error.stack) {
    errorResponse.stack = error.stack;
  }

  res.status(statusCode).json(errorResponse);
});

// Helper function for error messages
function getErrorMessage(statusCode) {
  const errors = {
    400: 'Bad Request',
    401: 'Unauthorized',
    403: 'Forbidden',
    404: 'Not Found',
    405: 'Method Not Allowed',
    429: 'Too Many Requests',
    500: 'Internal Server Error',
    503: 'Service Unavailable'
  };
  return errors[statusCode] || 'Internal Server Error';
}

// ======================================
// SECURITY HEADERS VALIDATION MIDDLEWARE
// ======================================

// Validate security headers are present (for monitoring)
app.use((req, res, next) => {
  const securityHeaders = [
    'Content-Security-Policy',
    'X-Content-Type-Options',
    'X-Frame-Options',
    'X-XSS-Protection',
    'Strict-Transport-Security'
  ];

  // Check if security headers are present
  const missingHeaders = securityHeaders.filter(header => !res.get(header));

  if (missingHeaders.length > 0 && NODE_ENV === 'production') {
    console.warn('Missing security headers:', missingHeaders);
  }

  next();
});

// ======================================
// SERVER STARTUP & GRACEFUL SHUTDOWN
// ======================================

const server = app.listen(PORT, () => {
  console.log(`
🚀 Server started successfully!
   Environment: ${NODE_ENV}
   Port: ${PORT}
   Time: ${new Date().toISOString()}
   Security Features Enabled:
     ✓ Helmet.js security headers
     ✓ CORS protection
     ✓ Rate limiting (100 req/15 min per IP)
     ✓ Input validation
     ✓ Error handling middleware
     ✓ Email masking for unauthenticated users
  `);
});

// Graceful shutdown handlers
const shutdownSignals = ['SIGTERM', 'SIGINT', 'SIGUSR2'];

shutdownSignals.forEach(signal => {
  process.on(signal, () => {
    console.log(`\n⚠️  Received ${signal}. Starting graceful shutdown...`);

    // Stop accepting new requests
    server.close((err) => {
      if (err) {
        console.error('Error during server close:', err);
        process.exit(1);
      }

      console.log('✅ Server closed successfully');
      console.log('🔄 Performing cleanup tasks...');

      // Perform any additional cleanup here
      // (close database connections, flush logs, etc.)

      setTimeout(() => {
        console.log('👋 Shutdown complete');
        process.exit(0);
      }, 1000);
    });

    // Force shutdown after 10 seconds if graceful shutdown doesn't complete
    setTimeout(() => {
      console.error('⚠️  Forcing shutdown after timeout');
      process.exit(1);
    }, 10000);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('🔥 Uncaught Exception:', error);
  // In production, you might want to restart the process here
  if (NODE_ENV === 'production') {
    process.exit(1);
  }
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('🔥 Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to restart the process here
  if (NODE_ENV === 'production') {
    process.exit(1);
  }
});

module.exports = { app, server };

