// Enhanced application with improved error handling and input validation
// Security best practices implemented

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const expressSanitizer = require('express-sanitizer');

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// 1. Set security headers using Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Enable CORS with appropriate restrictions
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With']
}));

// 3. Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skipSuccessfulRequests: false
});
app.use('/api/', limiter); // Apply to all routes starting with /api/

// 4. Body parsing with size limits
app.use(express.json({
  limit: '10kb', // Limit JSON payload size
  verify: (req, res, buf) => {
    // Reject requests with unexpected content types
    const contentType = req.headers['content-type'] || '';
    if (contentType.includes('application/json') && !isValidJSONString(buf.toString())) {
      throw new Error('Invalid JSON payload');
    }
  }
}));
app.use(express.urlencoded({
  extended: true,
  limit: '10kb' // Limit URL-encoded payload size
}));

// 5. Input sanitization
app.use(expressSanitizer());

// ==================== ERROR HANDLING MIDDLEWARE ====================

// Custom error class for better error handling
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.originalUrl} ${res.statusCode} ${duration}ms - IP: ${req.ip}`);
  });
  next();
});

// ==================== INPUT VALIDATION FUNCTIONS ====================

// Validate email format
const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email) && email.length <= 254;
};

// Validate user name
const validateName = (name) => {
  return typeof name === 'string' && 
         name.trim().length >= 2 && 
         name.trim().length <= 50 &&
         /^[a-zA-Z\s\-']+$/.test(name.trim());
};

// Validate numeric ID
const validateId = (id) => {
  const num = Number(id);
  return !isNaN(num) && Number.isInteger(num) && num > 0 && num <= 1000000;
};

// Validate query parameters
const validateQueryParams = (params) => {
  // Ensure no suspicious characters in query params
  const suspiciousPattern = /[<>'"]|%3C|%3E|%27|%22|javascript:|data:|vbscript:/i;
  return !suspiciousPattern.test(params);
};

// Validate JSON string
function isValidJSONString(str) {
  try {
    JSON.parse(str);
    return true;
  } catch (e) {
    return false;
  }
}

// ==================== ROUTES WITH INPUT VALIDATION ====================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    // Validate any query parameters if present
    if (Object.keys(req.query).length > 0) {
      const queryString = JSON.stringify(req.query);
      if (!validateQueryParams(queryString)) {
        throw new AppError('Invalid query parameters', 400);
      }
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memoryUsage: process.memoryUsage()
    });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with parameter validation
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters
    const { id, limit, offset } = req.query;

    // Validate id parameter if provided
    if (id && !validateId(id)) {
      throw new AppError('Invalid user ID format', 400);
    }

    // Validate limit parameter if provided
    if (limit && (!validateId(limit) || limit > 100)) {
      throw new AppError('Limit must be a positive integer and not exceed 100', 400);
    }

    // Validate offset parameter if provided
    if (offset && !validateId(offset)) {
      throw new AppError('Invalid offset value', 400);
    }

    // Validate query string for suspicious patterns
    const queryString = JSON.stringify(req.query);
    if (!validateQueryParams(queryString)) {
      throw new AppError('Invalid query parameters', 400);
    }

    // Sample data - in real app would come from database
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        role: 'user'
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        role: 'user'
      },
    ];

    // Apply filtering if ID is specified
    let filteredUsers = users;
    if (id) {
      filteredUsers = users.filter(user => user.id === parseInt(id, 10));
    }

    // Apply pagination
    const pageLimit = parseInt(limit || '10', 10);
    const pageOffset = parseInt(offset || '0', 10);
    const paginatedUsers = filteredUsers.slice(pageOffset, pageOffset + pageLimit);

    res.json({
      success: true,
      data: paginatedUsers,
      pagination: {
        total: filteredUsers.length,
        limit: pageLimit,
        offset: pageOffset,
        hasMore: pageOffset + pageLimit < filteredUsers.length
      }
    });

  } catch (error) {
    next(error);
  }
});

// Example endpoint for creating users with comprehensive validation
app.post('/users', (req, res, next) => {
  try {
    // Sanitize input
    req.body.name = req.sanitize(req.body.name || '');
    req.body.email = req.sanitize(req.body.email || '');

    // Validate required fields
    const { name, email } = req.body;

    if (!name || !email) {
      throw new AppError('Name and email are required', 400);
    }

    if (!validateName(name)) {
      throw new AppError('Invalid name format. Name must be 2-50 characters and contain only letters, spaces, hyphens, and apostrophes', 400);
    }

    if (!validateEmail(email)) {
      throw new AppError('Invalid email format', 400);
    }

    // Additional security checks
    if (Object.keys(req.body).length > 10) {
      throw new AppError('Too many fields in request body', 400);
    }

    // In a real application, you would save to database here
    const newUser = {
      id: Date.now(), // Temporary ID generation
      name: name.trim(),
      email: email.toLowerCase().trim(),
      role: 'user',
      createdAt: new Date().toISOString()
    };

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: newUser
    });

  } catch (error) {
    next(error);
  }
});

// ==================== ERROR HANDLING MIDDLEWARE ====================

// 404 handler for undefined routes
app.all('*', (req, res, next) => {
  next(new AppError(`Cannot find ${req.originalUrl} on this server`, 404));
});

// Global error handling middleware
app.use((err, req, res, next) => {
  // Default values
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Log error for monitoring
  console.error({
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.originalUrl,
    ip: req.ip,
    error: {
      message: err.message,
      stack: process.env.NODE_ENV === 'production' ? undefined : err.stack,
      statusCode: err.statusCode
    }
  });

  // Different response for production vs development
  if (process.env.NODE_ENV === 'production') {
    if (err.isOperational) {
      // Operational, trusted error: send message to client
      res.status(err.statusCode).json({
        status: err.status,
        message: err.message
      });
    } else {
      // Programming or other unknown error: don't leak error details
      console.error('ERROR 💥', err);
      res.status(500).json({
        status: 'error',
        message: 'Something went wrong!'
      });
    }
  } else {
    // Development environment: send detailed error
    res.status(err.statusCode).json({
      status: err.status,
      error: err,
      message: err.message,
      stack: err.stack
    });
  }
});

// ==================== SERVER SETUP ====================

const port = process.env.PORT || 3000;

const server = app.listen(port, () => {
  console.log(`Server running on port ${port} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION 💥 Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION 💥 Shutting down...');
  console.error(err.name, err.message);
  process.exit(1);
});

// Handle SIGTERM for graceful shutdown
process.on('SIGTERM', () => {
  console.log('👋 SIGTERM RECEIVED. Shutting down gracefully');
  server.close(() => {
    console.log('💥 Process terminated!');
  });
});

module.exports = app;

