// Improved Express application with security best practices
// Enhanced error handling and input validation

const express = require('express');
const cors = require('cors');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult, param } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Set security headers

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing middleware
app.use(express.json({ limit: '10kb' })); // Limit request body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware
app.use((req, res, next) => {
  console.log({
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.url,
    ip: req.ip,
    userAgent: req.get('User-Agent')
  });
  next();
});

// Health endpoint with input validation
app.get('/health', [
  query('detailed').optional().isBoolean().withMessage('detailed must be a boolean')
], (req, res) => {
  // Check validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      errors: errors.array().map(err => ({
        param: err.param,
        msg: err.msg,
        value: err.value
      }))
    });
  }

  try {
    const detailed = req.query.detailed === 'true';
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };

    if (detailed) {
      healthData.environment = process.env.NODE_ENV || 'development';
      healthData.nodeVersion = process.version;
    }

    res.json(healthData);
  } catch (error) {
    console.error('Health endpoint error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with input validation
app.get('/users', [
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
  query('active').optional().isBoolean().withMessage('Active must be a boolean')
], (req, res) => {
  // Check validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      errors: errors.array().map(err => ({
        param: err.param,
        msg: err.msg,
        value: err.value
      }))
    });
  }

  try {
    // Sample user data (in production, this would come from a database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', active: true },
      { id: 2, name: 'Bob', email: 'bob@example.com', active: true },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', active: false },
      { id: 4, name: 'Diana', email: 'diana@example.com', active: true }
    ];

    // Apply filters based on query parameters
    let filteredUsers = [...allUsers];

    // Filter by active status if provided
    if (req.query.active !== undefined) {
      const activeFilter = req.query.active === 'true';
      filteredUsers = filteredUsers.filter(user => user.active === activeFilter);
    }

    // Apply pagination
    const offset = req.query.offset ? parseInt(req.query.offset, 10) : 0;
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;

    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    // Sanitize output (remove sensitive data if needed)
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name,
      active: user.active
      // Email is omitted for security in this example
    }));

    res.json({
      data: sanitizedUsers,
      metadata: {
        total: filteredUsers.length,
        offset,
        limit,
        hasMore: offset + limit < filteredUsers.length
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Get user by ID endpoint with validation
