// Secure Express.js application with comprehensive error handling and input validation
// Security best practices implemented

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const expressValidator = require('express-validator');
const morgan = require('morgan');
const app = express();

// ================ CONSTANTS & CONFIGURATION ================
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ================ SECURITY MIDDLEWARE ================

// 1. Helmet.js for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  crossOriginEmbedderPolicy: false, // Adjust based on your needs
}));

// 2. CORS configuration
app.use(cors({
  origin: NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] // Specify production domains
    : ['http://localhost:3000', 'http://localhost:8080'],
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

// 3. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use('/api/', limiter); // Apply to all API routes

// 4. Request size limiting
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Limit URL-encoded body size

// ================ LOGGING ================
// Use morgan for request logging
if (NODE_ENV === 'development') {
  app.use(morgan('dev')); // Detailed logs for development
} else {
  app.use(morgan('combined')); // Standard Apache combined log format for production
}

// ================ HEALTH CHECK ENDPOINT ================
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      environment: NODE_ENV
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error in health check' 
    });
  }
});

// ================ USERS ENDPOINT WITH VALIDATION ================
app.get('/users', (req, res) => {
  try {
    const { page = 1, limit = 10 } = req.query;

    // Input validation
    const parsedPage = parseInt(page, 10);
    const parsedLimit = parseInt(limit, 10);

    if (isNaN(parsedPage) || isNaN(parsedLimit)) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        message: 'Page and limit must be valid numbers'
      });
    }

    if (parsedPage < 1 || parsedLimit < 1) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        message: 'Page and limit must be positive numbers'
      });
    }

    if (parsedLimit > 100) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        message: 'Limit cannot exceed 100'
      });
    }

    // Mock database data with pagination
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' },
    ];

    // Calculate pagination
    const startIndex = (parsedPage - 1) * parsedLimit;
    const endIndex = parsedPage * parsedLimit;
    const paginatedUsers = users.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      pagination: {
        page: parsedPage,
        limit: parsedLimit,
        total: users.length,
        pages: Math.ceil(users.length / parsedLimit),
        hasNext: endIndex < users.length,
        hasPrev: parsedPage > 1
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Failed to retrieve users',
      timestamp: new Date().toISOString()
    });
  }
});

// ================ ADVANCED USER ENDPOINT WITH STRICT VALIDATION ================
app.get('/users/:id', (req, res) => {
  try {
    const userId = parseInt(req.params.id, 10);

    // Strict input validation
    if (isNaN(userId) || userId <= 0) {
      return res.status(400).json({
        error: 'Invalid user ID',
        message: 'User ID must be a positive integer'
      });
    }

    // Mock database data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: 'User not found',
        message: `User with ID ${userId} does not exist`
      });
    }

    // Sanitize response data (remove sensitive fields if any)
    res.json({
      data: user,
      links: {
        self: `/users/${userId}`,
        all: '/users'
      }
    });

  } catch (error) {
    console.error('User detail endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Failed to retrieve user details',
      timestamp: new Date().toISOString()
    });
  }
});

// ================ 404 HANDLER ================
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.originalUrl}`,
    timestamp: new Date().toISOString()
  });
});

// ================ GLOBAL ERROR HANDLER ================
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Default error response
  const statusCode = err.statusCode || 500;
  const message = NODE_ENV === 'production' 
    ? 'Internal server error'
    : err.message || 'Internal server error';

  res.status(statusCode).json({
    error: 'Internal Server Error',
    message: message,
    ...(NODE_ENV === 'development' && { stack: err.stack }),
    timestamp: new Date().toISOString()
  });
});

// ================ SERVER STARTUP ================
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// ================ GRACEFUL SHUTDOWN ================
const gracefulShutdown = () => {
  console.log('Received shutdown signal, gracefully shutting down...');

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

// Handle shutdown signals
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  gracefulShutdown();
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown();
});

module.exports = app;

