// Enhanced app.js with focused security improvements
// Minimal changes to maintain original functionality while adding security

const express = require('express');
const app = express();

// ==================== SECURITY IMPROVEMENTS ====================

// 1. Security Headers Middleware (minimal implementation without external dependencies)
app.use((req, res, next) => {
    // Basic security headers
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('X-Frame-Options', 'DENY');
    res.setHeader('X-XSS-Protection', '1; mode=block');
    res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
    next();
});

// 2. Request Parsing with Limits (prevent DoS attacks)
app.use(express.json({ 
    limit: '1mb', // Limit request body size
    strict: true  // Only accept arrays and objects
}));

app.use(express.urlencoded({ 
    extended: true, 
    limit: '1mb',
    parameterLimit: 50 // Limit number of parameters
}));

// 3. Input Validation Middleware
const validateQueryParams = (req, res, next) => {
    // Validate all string parameters to prevent injection attacks
    const stringParams = ['search', 'sort', 'name'];

    for (const param of stringParams) {
        if (req.query[param]) {
            // Basic sanitization - remove potentially dangerous characters
            const sanitized = req.query[param].toString().replace(/[<>'"`;\/\\]/g, '');
            if (sanitized !== req.query[param]) {
                return res.status(400).json({ 
                    error: 'Invalid input detected',
                    message: `Parameter '${param}' contains invalid characters`
                });
            }

            // Length validation
            if (sanitized.length > 100) {
                return res.status(400).json({ 
                    error: 'Input too long',
                    message: `Parameter '${param}' exceeds maximum length of 100 characters`
                });
            }
        }
    }

    // Validate numeric parameters
    const numericParams = ['id', 'page', 'limit'];
    for (const param of numericParams) {
        if (req.query[param] || req.params[param]) {
            const value = req.query[param] || req.params[param];
            const num = parseInt(value, 10);

            if (isNaN(num) || num <= 0 || num > 1000000) {
                return res.status(400).json({ 
                    error: 'Invalid numeric input',
                    message: `Parameter '${param}' must be a positive number less than 1,000,000`
                });
            }
        }
    }

    next();
};

// 4. Rate Limiting (basic in-memory implementation)
const requestCounts = new Map();
const RATE_LIMIT = {
    windowMs: 15 * 60 * 1000, // 15 minutes
    maxRequests: 100
};

app.use((req, res, next) => {
    const ip = req.ip || req.connection.remoteAddress;
    const now = Date.now();

    if (!requestCounts.has(ip)) {
        requestCounts.set(ip, { count: 1, resetTime: now + RATE_LIMIT.windowMs });
    } else {
        const record = requestCounts.get(ip);

        if (now > record.resetTime) {
            // Reset counter if window has passed
            record.count = 1;
            record.resetTime = now + RATE_LIMIT.windowMs;
        } else if (record.count >= RATE_LIMIT.maxRequests) {
            // Too many requests
            const retryAfter = Math.ceil((record.resetTime - now) / 1000);
            res.setHeader('Retry-After', retryAfter);
            return res.status(429).json({
                error: 'Too Many Requests',
                message: `Rate limit exceeded. Try again in ${retryAfter} seconds.`,
                retryAfter
            });
        } else {
            record.count++;
        }
    }

    // Set rate limit headers
    const record = requestCounts.get(ip);
    res.setHeader('X-RateLimit-Limit', RATE_LIMIT.maxRequests);
    res.setHeader('X-RateLimit-Remaining', Math.max(0, RATE_LIMIT.maxRequests - record.count));
    res.setHeader('X-RateLimit-Reset', Math.ceil(record.resetTime / 1000));

    next();
});

// ==================== ERROR HANDLING IMPROVEMENTS ====================

// 5. Global Error Handler
app.use((err, req, res, next) => {
    console.error(`[${new Date().toISOString()}] Error: ${err.message}`);

    // Don't expose stack traces in production
    const errorResponse = {
        error: 'Internal Server Error',
        timestamp: new Date().toISOString()
    };

    // Only include details in development
    if (process.env.NODE_ENV !== 'production') {
        errorResponse.message = err.message;
        errorResponse.stack = err.stack;
    }

    res.status(err.status || 500).json(errorResponse);
});

// 6. Async Error Handler Wrapper
const asyncHandler = (fn) => (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
};

// 7. 404 Handler with Security Considerations
app.use((req, res) => {
    // Log 404 attempts (potential scanning)
    console.warn(`[${new Date().toISOString()}] 404: ${req.method} ${req.url} from ${req.ip}`);

    res.status(404).json({
        error: 'Not Found',
        message: `Cannot ${req.method} ${req.url}`,
        timestamp: new Date().toISOString()
    });
});

// ==================== ENHANCED ENDPOINTS ====================

// Health endpoint with input validation
app.get('/health', validateQueryParams, asyncHandler(async (req, res) => {
    const healthData = {
        status: 'ok',
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        environment: process.env.NODE_ENV || 'development'
    };

    res.json(healthData);
}));

// Users endpoint with comprehensive validation
app.get('/users', validateQueryParams, asyncHandler(async (req, res) => {
    // Additional endpoint-specific validation
    const { page = 1, limit = 10, search, sort } = req.query;

    // Validate pagination parameters
    const pageNum = parseInt(page, 10);
    const limitNum = parseInt(limit, 10);

    if (pageNum < 1 || pageNum > 1000) {
        throw new Error('Page must be between 1 and 1000');
    }

    if (limitNum < 1 || limitNum > 100) {
        throw new Error('Limit must be between 1 and 100');
    }

    // Simulated database query with error handling
    let users;
    try {
        users = [
            { id: 1, name: 'Alice', email: 'alice@example.com' },
            { id: 2, name: 'Bob', email: 'bob@example.com' },
        ];

        // Apply filtering if search provided
        if (search) {
            const searchLower = search.toLowerCase();
            users = users.filter(user => 
                user.name.toLowerCase().includes(searchLower) ||
                user.email.toLowerCase().includes(searchLower)
            );
        }

        // Apply sorting if sort provided
        if (sort && ['name', 'id', 'email'].includes(sort)) {
            users.sort((a, b) => a[sort].localeCompare(b[sort]));
        }

    } catch (dbError) {
        // Log database errors but don't expose details
        console.error('Database error:', dbError.message);
        throw new Error('Unable to retrieve user data');
    }

    // Calculate pagination
    const startIndex = (pageNum - 1) * limitNum;
    const endIndex = Math.min(startIndex + limitNum, users.length);
    const paginatedUsers = users.slice(startIndex, endIndex);

    res.json({
        data: paginatedUsers,
        meta: {
            page: pageNum,
            limit: limitNum,
            total: users.length,
            totalPages: Math.ceil(users.length / limitNum)
        }
    });
}));

// ==================== SERVER SETUP ====================

const PORT = process.env.PORT || 3000;

// Graceful shutdown handling
const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
    console.log(`Security features enabled:
    - Security headers
    - Input validation
    - Rate limiting (${RATE_LIMIT.maxRequests}/15min)
    - Request size limits (1MB)
    - Comprehensive error handling`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
    console.log('SIGTERM received, starting graceful shutdown');
    server.close(() => {
        console.log('Server closed');
        process.exit(0);
    });
});

process.on('SIGINT', () => {
    console.log('SIGINT received, shutting down');
    server.close(() => {
        process.exit(0);
    });
});

module.exports = app;

