// Improved application with security best practices
// Enhanced error handling and input validation

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const validator = require('validator'); // for input validation and sanitization

const app = express();

// ============= SECURITY MIDDLEWARES =============

// 1. Helmet.js for security headers
app.use(helmet());

// 2. CORS configuration (restrict to trusted origins)
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 3. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skipSuccessfulRequests: false,
  keyGenerator: (req) => req.ip // use IP address for rate limiting
});
app.use('/api/', limiter); // Apply to all API routes

// 4. Request logging with morgan
app.use(morgan('combined'));

// 5. Body parsing middleware with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payloads
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============= CUSTOM MIDDLEWARES =============

// Request validation middleware
const validateRequest = (req, res, next) => {
  try {
    // Validate Content-Type for POST/PUT requests
    if (['POST', 'PUT', 'PATCH'].includes(req.method)) {
      const contentType = req.headers['content-type'];
      if (!contentType || !contentType.includes('application/json')) {
        return res.status(415).json({
          error: 'Unsupported Media Type',
          message: 'Content-Type must be application/json'
        });
      }
    }
    next();
  } catch (error) {
    next(error);
  }
};
app.use(validateRequest);

// Input sanitization middleware
const sanitizeInput = (req, res, next) => {
  try {
    // Sanitize query parameters
    if (req.query) {
      Object.keys(req.query).forEach(key => {
        if (typeof req.query[key] === 'string') {
          req.query[key] = validator.escape(req.query[key]);
        }
      });
    }

    // Sanitize body parameters
    if (req.body && typeof req.body === 'object') {
      sanitizeObject(req.body);
    }

    next();
  } catch (error) {
    next(error);
  }
};

function sanitizeObject(obj) {
  Object.keys(obj).forEach(key => {
    if (typeof obj[key] === 'string') {
      obj[key] = validator.escape(obj[key]);
    } else if (typeof obj[key] === 'object' && obj[key] !== null) {
      sanitizeObject(obj[key]);
    }
  });
}

app.use(sanitizeInput);

// ============= ROUTES WITH IMPROVED ERROR HANDLING =============

// Health check with error handling
app.get('/health', async (req, res, next) => {
  try {
    // Simulate some health checks
    const healthChecks = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      nodeVersion: process.version,
      environment: process.env.NODE_ENV || 'development'
    };

    // Add additional health checks here (database, external services, etc.)
    // Example: await checkDatabaseConnection();

    res.json(healthChecks);
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters
    const { page, limit, sort } = req.query;

    // Type validation
    if (page && !validator.isInt(page, { min: 1 })) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Page must be a positive integer'
      });
    }

    if (limit && !validator.isInt(limit, { min: 1, max: 100 })) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Limit must be between 1 and 100'
      });
    }

    if (sort && !['name', 'email', 'id'].includes(sort)) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Sort field must be one of: name, email, id'
      });
    }

    // Simulate database query with pagination
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        created_at: new Date().toISOString()
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        created_at: new Date().toISOString()
      },
      { 
        id: 3, 
        name: 'Charlie', 
        email: 'charlie@example.com',
        created_at: new Date().toISOString()
      }
    ];

    // Apply filtering/sorting/pagination logic here
    let result = users;

    // Apply sorting
    if (sort) {
      result = result.sort((a, b) => a[sort].localeCompare(b[sort]));
    }

    // Apply pagination
    const pageNum = parseInt(page) || 1;
    const limitNum = parseInt(limit) || 10;
    const startIndex = (pageNum - 1) * limitNum;
    const endIndex = pageNum * limitNum;
    const paginatedResult = result.slice(startIndex, endIndex);

    res.json({
      data: paginatedResult,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: users.length,
        totalPages: Math.ceil(users.length / limitNum)
      }
    });

  } catch (error) {
    next(error);
  }
});

// New route with more comprehensive input validation
app.post('/users', (req, res, next) => {
  try {
    const { name, email, password } = req.body;

    // Validate required fields
    if (!name || !email || !password) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Name, email, and password are required'
      });
    }

    // Validate email format
    if (!validator.isEmail(email)) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Invalid email format'
      });
    }

    // Validate name length
    if (!validator.isLength(name, { min: 2, max: 50 })) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Name must be between 2 and 50 characters'
      });
    }

    // Validate password strength
    if (!validator.isStrongPassword(password, {
      minLength: 8,
      minLowercase: 1,
      minUppercase: 1,
      minNumbers: 1,
      minSymbols: 1
    })) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Password must be at least 8 characters with uppercase, lowercase, number, and symbol'
      });
    }

    // Sanitize inputs (already done by middleware, but double-check)
    const sanitizedEmail = validator.normalizeEmail(email);

    // In a real app, you would save to database here
    // const newUser = await User.create({ name, email: sanitizedEmail, password: hashedPassword });

    res.status(201).json({
      message: 'User created successfully',
      user: {
        id: Math.floor(Math.random() * 1000), // Simulate ID generation
        name,
        email: sanitizedEmail
        // Never return password or sensitive data
      }
    });

  } catch (error) {
    next(error);
  }
});

// Example route with parameter validation
app.get('/users/:id', (req, res, next) => {
  try {
    const { id } = req.params;

    // Validate ID parameter
    if (!validator.isInt(id, { min: 1 })) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'User ID must be a positive integer'
      });
    }

    // Validate that ID doesn't contain SQL injection patterns
    if (validator.contains(id, [';', '--', '/*', '*/', "'", '"', '`'])) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Invalid user ID format'
      });
    }

    // Simulate database lookup
    const userId = parseInt(id);
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' }
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: `User with ID ${id} not found`
      });
    }

    res.json(user);

  } catch (error) {
    next(error);
  }
});

// ============= ERROR HANDLING MIDDLEWARES =============

// 404 handler for undefined routes
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.originalUrl}`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error(`[${new Date().toISOString()}] Error:`, error);

  // Default error status and message
  const statusCode = error.statusCode || 500;
  const message = error.message || 'Internal Server Error';

  // Don't expose stack traces in production
  const response = {
    error: 'Internal Server Error',
    message: message
  };

  // Include stack trace in development
  if (process.env.NODE_ENV === 'development') {
    response.stack = error.stack;
  }

  // Handle specific error types
  if (error.name === 'ValidationError') {
    response.error = 'Validation Error';
    response.details = error.details;
  }

  if (error.name === 'UnauthorizedError') {
    response.error = 'Unauthorized';
    response.message = 'Invalid or missing authentication token';
  }

  res.status(statusCode).json(response);
});

// ============= SERVER SETUP =============

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown handling
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to exit the process
  // process.exit(1);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, you might want to exit the process
  // process.exit(1);
});

// Graceful shutdown
const shutdown = () => {
  console.log('Received shutdown signal, closing server...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app;

