// Minimal improvements to original app.js with security best practices
// Focuses on essential security measures without many dependencies

const express = require('express');
const app = express();

// ============= BASIC SECURITY MIDDLEWARES =============

// 1. Security headers (can use helmet or implement manually)
app.use((req, res, next) => {
  // Basic security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'");

  // Remove server information
  res.removeHeader('X-Powered-By');
  next();
});

// 2. Request size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 3. Basic input sanitization middleware
const sanitizeInput = (req, res, next) => {
  // Sanitize query parameters
  if (req.query) {
    for (const key in req.query) {
      if (typeof req.query[key] === 'string') {
        // Basic XSS protection - escape HTML
        req.query[key] = req.query[key]
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;')
          .replace(/'/g, '&#x27;')
          .replace(/\//g, '&#x2F;');
      }
    }
  }
  next();
};
app.use(sanitizeInput);

// ============= IMPROVED ROUTES WITH ERROR HANDLING =============

