// Enhanced application with security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');

const app = express();

// ==================== ENVIRONMENT VALIDATION ====================
const requiredEnvVars = ['PORT', 'NODE_ENV'];
requiredEnvVars.forEach(envVar => {
  if (!process.env[envVar]) {
    console.error(`[SECURITY] Missing required environment variable: ${envVar}`);
    process.exit(1);
  }
});

const isProduction = process.env.NODE_ENV === 'production';

// ==================== SECURITY MIDDLEWARE ====================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Disable X-Powered-By header
app.disable('x-powered-by');

// Rate limiting (prevent DoS attacks)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false
});
app.use(limiter);

// Body parsing with size limits (prevent large payload attacks)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ==================== HEALTH ENDPOINT ====================
app.get('/health', (req, res) => {
  try {
    // Validate health status
    const healthStatus = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };

    // Validate timestamp format
    if (!Date.parse(healthStatus.timestamp)) {
      throw new Error('Invalid timestamp generated');
    }

    // Add security headers specifically for health endpoint
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, private');
    res.json(healthStatus);
  } catch (error) {
    console.error('[ERROR] Health check failed:', error);
    res.status(503).json({
      status: 'error',
      message: 'Service health check failed',
      timestamp: new Date().toISOString()
    });
  }
});

// ==================== USERS ENDPOINT WITH VALIDATION ====================
app.get('/users', 
  [
    // Input validation for query parameters
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be an integer between 1 and 100')
      .toInt(),

    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),

    query('search')
      .optional()
      .trim()
      .escape() // Sanitize input to prevent XSS
      .isLength({ max: 100 })
      .withMessage('Search query must be less than 100 characters')
  ],
  (req, res) => {
    try {
      // Validate request
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          errors: errors.array(),
          message: 'Validation failed'
        });
      }

      // Extract and sanitize validated parameters
      const { limit = 10, offset = 0, search } = req.query;

      // Simulate database query (in real app, parameterize SQL queries)
      let users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply filters (simulated)
      if (search) {
        users = users.filter(user => 
          user.name.toLowerCase().includes(search.toLowerCase()) ||
          user.email.toLowerCase().includes(search.toLowerCase())
        );
      }

      // Apply pagination
      const paginatedUsers = users.slice(offset, offset + limit);

      // Set security headers for API response
      res.setHeader('Content-Type', 'application/json');
      res.setHeader('Cache-Control', 'no-store');

      res.json({
        data: paginatedUsers,
        meta: {
          total: users.length,
          limit: parseInt(limit),
          offset: parseInt(offset),
          hasMore: users.length > offset + limit
        }
      });

    } catch (error) {
      console.error('[ERROR] Users endpoint failed:', error);

      // Log but don't expose internal errors
      res.status(500).json({
        error: isProduction ? 'Internal server error' : error.message,
        message: 'Failed to retrieve users'
      });
    }
  }
);

// ==================== ERROR HANDLING MIDDLEWARE ====================

// Global error handler
app.use((err, req, res, next) => {
  // Log error details
  console.error('[ERROR] Unhandled error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Determine appropriate status code
  const statusCode = err.status || err.statusCode || 500;

  // Format error response
  const errorResponse = {
    error: isProduction ? 'Internal server error' : err.message,
    ...(isProduction ? {} : { stack: err.stack }),
    timestamp: new Date().toISOString()
  };

  // Remove stack trace from client-facing response in production
  res.status(statusCode).json(errorResponse);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested resource ${req.url} was not found`,
    timestamp: new Date().toISOString()
  });
});

// ==================== SECURITY LOGGING ====================

// Request logging middleware (security event tracking)
app.use((req, res, next) => {
  const startTime = Date.now();

  // Log completion
  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const logEntry = {
      timestamp: new Date().toISOString(),
      method: req.method,
      url: req.url,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('User-Agent')
    };

    console.log('[ACCESS]', JSON.stringify(logEntry));

    // Log security events (401, 403, 404, 429, 500, etc.)
    if ([401, 403, 429, 500].includes(res.statusCode)) {
      console.warn('[SECURITY] Potential security event:', logEntry);
    }
  });

  next();
});

// ==================== SERVER SETUP ====================
const PORT = process.env.PORT || 3000;

// Graceful shutdown
const server = app.listen(PORT, () => {
  console.log(`🚀 Server running on port ${PORT}`);
  console.log(`🔒 Security features enabled:`);
  console.log(`   - Helmet security headers`);
  console.log(`   - Rate limiting (100 req/15min per IP)`);
  console.log(`   - Input validation and sanitization`);
  console.log(`   - Environment validation`);
  console.log(`   - Comprehensive error handling`);
  console.log(`   - Security event logging`);
});

// Graceful shutdown handlers
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Starting graceful shutdown...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received. Starting graceful shutdown...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('[CRITICAL] Unhandled promise rejection:', reason);
  // In production, might want to restart the process
  if (isProduction) {
    server.close(() => {
      process.exit(1);
    });
  }
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('[CRITICAL] Uncaught exception:', error);
  // In production, might want to restart the process
  if (isProduction) {
    server.close(() => {
      process.exit(1);
    });
  }
});

module.exports = app;

